window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q05"]=window.__LIBQ["the-gioi-hoan-my"]["q05"]||{};window.__LIBQ["the-gioi-hoan-my"]["q05"]["artifacts"]={"updatedAt":"2026-07-21","count":153,"artifacts":[{"id":"thai-duong-thach","name":"Thái Dương thạch","cn":"","aliases":["Thần nhật đỉnh cấp"],"category":"nguyen-lieu","categoryLabel":"Bảo tài","phamCap":"Thần nhật đỉnh cấp","soHuu":["Thạch Hạo"],"trangThai":"Được Thạch Hạo giữ lại để tìm hiểu","blurb":"Một mảnh Thần nhật đỉnh cấp bị đại năng thượng cổ chém rớt, vốn ẩn trong lớp vỏ giống Địa Hỏa thạch.","detail":"Bề ngoài là tảng đá đen xì giống Địa Hỏa thạch, nhưng trung tâm chứa chùm sáng đỏ đậm có thể làm tổn thương mắt khi quan sát bằng Trùng Đồng. Tiểu tháp nhận ra đây là một miếng Thái Dương thuộc cấp Thần nhật đỉnh cấp, bên trong còn ẩn chứa kiếm ý đáng sợ. Thạch Hạo dùng bảo châu Bắc Hải đổi lấy rồi giữ lại để tìm hiểu trước khi giao cho Tiểu tháp nuốt.","nguon":["@c0405"]},{"id":"bon-tran-ky-tu-tuong","name":"Bốn trận kỳ Tứ Tượng","cn":"","category":"phap-bao","categoryLabel":"Pháp khí trận kỳ","phamCap":"Có thể do Tôn giả luyện chế","soHuu":["Lão già Viêm Mãng tộc"],"trangThai":"Đã được dùng để dựng sát trận Tứ Tượng","blurb":"Bốn trận kỳ được lão già Viêm Mãng tộc dùng để bao phủ Thạch Hạo và dựng sát trận Tứ Tượng.","detail":"Bốn đại kỳ diễn sinh Tứ Tượng, vây nhốt một tiểu thiên địa để phối hợp luyện hóa mục tiêu. Nhiều người chứng kiến phỏng đoán chúng phần nhiều do Tôn giả luyện chế.","nguon":["@c0406"]},{"id":"thi-the-viem-mang-vuong","name":"Thi thể Viêm Mãng Vương","cn":"","category":"nguyen-lieu","categoryLabel":"Bảo dược huyết nhục","phamCap":"Vương giả","soHuu":["Thạch Hạo"],"trangThai":"Đã được Thạch Hạo thu giữ","blurb":"Bản thể Viêm Mãng khổng lồ được Thạch Hạo thu giữ sau khi chém chết Viêm Mãng Vương.","detail":"Thi thể tuy không thuộc sinh linh thuần huyết nhưng là huyết nhục của dị thú cấp Vương giả, vì vậy vẫn được xem như bảo dược huyết nhục và có thể dùng làm nguyên liệu món ăn.","nguon":["@c0406"]},{"id":"vong-ngu-hanh-hang-nhai","name":"Vòng Ngũ Hành hàng nhái","cn":"","category":"phap-bao","categoryLabel":"Bảo cụ","phamCap":"Hàng nhái không trọn vẹn của bảo vật trấn giáo","soHuu":["Tần Thủ Thành"],"trangThai":"Đang được Tần Thủ Thành khống chế","blurb":"Chiếc vòng năm màu có thể phong tỏa không gian, giam cầm thân thể và chân nguyên. Tuy chỉ phát huy sức mạnh của bốn loại chân cốt, nó vẫn đủ sức trấn áp Vương giả.","detail":"Tần Thủ Thành tế chiếc vòng để phong tỏa toàn bộ đình viện, sau đó giải phóng những người ngoài cuộc nhưng tiếp tục giam Thạch Hạo, Cửu đầu sư tử và Đại Hồng Điểu. Bảo cụ diễn hóa một vùng như tiểu thiên địa, có thể hấp thu và phân giải ngoại lực theo ngũ hành; đây là hàng nhái không trọn vẹn của Vòng Ngũ Hành chính phẩm và chỉ phát huy uy lực của bốn loại chân cốt.","nguon":["@c0408"]},{"id":"vong-ngu-hanh-chinh-pham","name":"Vòng Ngũ Hành chính phẩm","cn":"","category":"phap-bao","categoryLabel":"Bảo vật trấn giáo","phamCap":"Một trong những bảo cụ mạnh nhất thời thượng cổ","soHuu":["Bất Lão sơn"],"trangThai":"Chưa được mang ra sử dụng","blurb":"Bảo vật trấn giáo của Bất Lão sơn, được luyện từ năm loại phù cốt nguyên thủy của hung thú cấp Thiên cùng nhiều bảo cốt và thần huyết. Nó có thể diễn biến ngũ hành và tự thành một giới.","detail":"Vòng Ngũ Hành chính phẩm từng khiến các Thần phải tránh lui và đã giết nhiều đại năng thời thượng cổ. Bảo vật có khả năng hấp thu, phân giải lực lượng thành ngũ hành; khi được tế luyện từng gây nên dị tượng rộng lớn. Chính phẩm không xuất hiện trực tiếp trong cuộc đối đầu tại khu vườn, còn chiếc vòng do Tần Thủ Thành sử dụng chỉ là một bản sao không trọn vẹn.","nguon":["@c0408"]},{"id":"loi-phu-cua-tan-thu-thanh","name":"Lôi phù của Tần Thủ Thành","cn":"","category":"phap-bao","categoryLabel":"Phù bảo","phamCap":"Chưa rõ","soHuu":["Tần Thủ Thành"],"trangThai":"Được dùng để công kích Thạch Hạo","blurb":"Lôi phù xuất hiện trong lòng bàn tay Tần Thủ Thành rồi giáng vô tận sấm sét xuống Thạch Hạo.","detail":"Sau khi dùng Vòng Ngũ Hành ép xuống và phong tỏa hư không, Tần Thủ Thành đánh ra lôi phù với ý định phế bỏ tu vi Thạch Hạo. Sấm sét từ phù bảo bao phủ mục tiêu trong lúc Thạch Hạo vẫn đang chịu sức giam cầm của chiếc vòng.","nguon":["@c0408"]},{"id":"ho-lo-den","name":"Hồ lô đen","cn":"","category":"phap-bao","categoryLabel":"Bảo cụ","phamCap":"Không rõ","soHuu":["Cường giả Hắc Vân tộc"],"trangThai":"Bị phá hủy","blurb":"Bảo cụ dùng ánh sáng đen để luyện hóa mục tiêu, thuộc sở hữu của cường giả Hắc Vân tộc.","detail":"Cường giả Hắc Vân tộc dùng hồ lô đen để luyện hóa Thạch Hạo. Kiếm khí của Thạch Hạo cắt vỡ hồ lô, khiến ánh sáng đen bên trong nổ tung và cuốn ngược chủ nhân vào trong.","nguon":["@c0409"]},{"id":"cap-sung-hoa-nguu","name":"Cặp sừng Hỏa Ngưu","cn":"","category":"phap-bao","categoryLabel":"Bảo cụ thân thể","phamCap":"Không rõ","soHuu":["Vương giả Hỏa Ngưu tộc"],"trangThai":"Bị chém rơi","blurb":"Cặp sừng của Vương giả Hỏa Ngưu tộc có thể hóa thành hai thanh kiếm đỏ đậm mang sức mạnh phù văn.","detail":"Vương giả Hỏa Ngưu tộc biến cặp sừng thành song kiếm đỏ đậm để hợp công Thạch Hạo. Hai thanh kiếm sau đó bị kiếm khí của Thạch Hạo chém rơi.","nguon":["@c0409"]},{"id":"hoang-kim-than-lo","name":"Hoàng Kim Thần Lô","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Không rõ","soHuu":["Cửu đầu sư tử"],"trangThai":"Được bộ tộc cho Cửu đầu sư tử mượn","blurb":"Một thần lô được bộ tộc Cửu đầu sư tử cho mượn để hỗ trợ quá trình rèn luyện và tăng tiến tu vi.","detail":"Cửu đầu sư tử sử dụng Hoàng Kim Thần Lô trong nhiều năm, phối hợp với Cửu Luyện chân huyết và phương thức luyện thể của Cổ thần để nhanh chóng tiến hóa, tiến gần tới sinh linh thuần huyết.","nguon":["@c0410"]},{"id":"cuu-luyen-chan-huyet","name":"Cửu Luyện chân huyết","cn":"","category":"nguyen-lieu","categoryLabel":"Nguyên liệu","phamCap":"Không rõ","soHuu":["Cửu đầu sư tử"],"trangThai":"Đã được dùng để tu luyện","blurb":"Chân huyết được Cửu đầu sư tử dùng để đoạt lấy thiên địa tạo hóa và nhanh chóng nâng cao tu vi.","detail":"Cửu Luyện chân huyết được sử dụng cùng Hoàng Kim Thần Lô và phương thức luyện thể của Cổ thần, giúp Cửu đầu sư tử tăng tiến tu vi và tiến gần tới sinh linh thuần huyết.","nguon":["@c0410"]},{"id":"hoa-ly-hoa-linh","name":"Hoa Ly Hỏa Linh","cn":"","category":"nguyen-lieu","categoryLabel":"Nguyên liệu","phamCap":"Không rõ","soHuu":["Nguyệt Thiền tiên tử"],"trangThai":"Đã được ngắt lấy tại Hỏa quật","blurb":"Một loại dược thảo mọc tại Hỏa quật, là dược liệu không thể thiếu cho việc luyện chế niết bàn.","detail":"Nguyệt Thiền tiên tử từng tới Hỏa quật và ngắt lấy Hoa Ly Hỏa Linh để chuẩn bị cho quá trình niết bàn. Hỏa quật quanh năm chìm trong lửa và có nhiệt độ trong động rất cao.","nguon":["@c0410"]},{"id":"tieu-niet-ban-dan","name":"Tiểu niết bàn đan","cn":"","category":"dan-duoc","categoryLabel":"Đan dược","phamCap":"Không rõ","soHuu":[],"trangThai":"Được nhắc đến trong luận bàn về đột phá","blurb":"Đan dược đặc biệt thích hợp với tu sĩ Liệt Trận cảnh, có thể mở thần tàng và hỗ trợ đột phá lên đại cảnh giới kế tiếp. (+) Kim đan có thể giúp Vương giả phá quan tiến vào cảnh giới Tôn giả. Thạch Hạo luyện thành hai lò, mỗi lò ba viên. [CAN-SOAT-GOP] (+) Bảo đan do Thạch Hạo luyện trước khi rời đi, có thể giúp Vương giả tiến lên Tôn Giả. [CAN-SOAT-GOP]","detail":"Sau khi đạt Liệt Trận Vương cảnh, tu sĩ rất khó tiếp tục đột phá chỉ bằng bản thân và thường cần dược thảo để rèn luyện thân thể. Tiểu niết bàn đan có công dụng mở thần tàng, hỗ trợ vượt qua cảnh giới này; linh dược tại các Thái Cổ Thần Sơn có thể dùng để luyện chế tiểu niết bàn đan cao cấp.","nguon":["@c0410","@c0558","@c0613"],"tabs":{}},{"id":"nam-phuong-thuoc-thuong-co-thach-toc","name":"Năm phương thuốc thượng cổ của Thạch tộc","cn":"","category":"khac","categoryLabel":"Phương thuốc","phamCap":"Thượng cổ","soHuu":["Thạch thôn"],"trangThai":"Được Thạch thôn bảo tồn đầy đủ","blurb":"Bộ năm phương thuốc là truyền thừa quan trọng nhất của Thạch tộc, có khả năng khai mở tiềm năng huyết nhục và tinh thần của người tu hành.","detail":"Các phương thuốc phối hợp dược liệu với âm dương, thủy hỏa để rèn luyện cả dược liệu lẫn người tu hành, giúp kích phát tiềm năng thân thể, tăng cường tinh thần và thực hiện niết bàn mà không để lại di chứng. Thạch thôn vẫn lưu truyền đủ năm phương từ thời thượng cổ, trong khi phần truyền thừa do hoàng tộc Thạch quốc nắm giữ đã thất lạc phương phối hợp quan trọng nhất.","nguon":["@c0411"]},{"id":"dinh-den-ky-la-thach-thon","name":"Đỉnh đen kỳ lạ của Thạch thôn","cn":"","category":"phap-bao","categoryLabel":"Dược đỉnh","phamCap":"Chưa rõ","soHuu":["Thạch thôn"],"trangThai":"Đang ở Thạch thôn","blurb":"Chiếc đỉnh đen kỳ lạ được dùng để rèn luyện huyết nhục bảo dược và từng phát ra âm thanh thần bí.","detail":"Khi nghe kể Thạch tộc có một chiếc đỉnh mạnh chuyên dùng rèn luyện thân thể, Thạch Hạo liên tưởng đến chiếc đỉnh đen tại Thạch thôn và nghi ngờ đây chính là bảo đỉnh truyền thừa ấy. Chiếc đỉnh từng phát ra âm thanh thần bí trong lúc rèn luyện huyết nhục bảo dược.","nguon":["@c0411"]},{"id":"truc-hoang-tuyen","name":"Trúc Hoàng Tuyền","cn":"","category":"nguyen-lieu","categoryLabel":"Nguyên liệu","phamCap":"Linh mộc kỳ lạ","soHuu":[],"trangThai":"Từng xuất hiện tại Thú sơn Tây Lăng","blurb":"Linh mộc quý hiếm, là chủ dược không thể thiếu và không thể thay thế trong phương thuốc Thạch Hạo cần.","detail":"Trúc Hoàng Tuyền từng xuất hiện tại Thú sơn Tây Lăng. Manh mối này khiến Thạch Hạo dự tính tiến vào khu cổ lăng nguy hiểm để tìm kiếm nó.","nguon":["@c0412"]},{"id":"phap-khi-than-linh-cua-bo-toc-van-hi","name":"Pháp khí Thần Linh của bộ tộc Vân Hi","cn":"","category":"phap-bao","categoryLabel":"Pháp khí","phamCap":"Thần Linh","soHuu":["Thạch Hạo"],"trangThai":"Một bộ phận quan trọng đang do Thạch Hạo nắm giữ","blurb":"Pháp khí vốn thuộc bộ tộc của Vân Hi, có thể hợp cùng bộ phận tương ứng để tạo thành một chiếc chìa khóa.","detail":"Khi tập hợp đủ một đôi, pháp khí sẽ hóa thành chìa khóa mở môn hộ phủ bụi có liên quan đến bí mật thần vực. Vân Hi muốn dùng pháp khí Thần Linh khác để trao đổi, nhưng Thạch Hạo kiên quyết giữ lại theo lời căn dặn của Nhị Ngốc Tử.","nguon":["@c0413"]},{"id":"hu-khong-thu-bi","name":"Hư Không thú bì","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo không gian","phamCap":"Da Thần Thú quý hiếm","soHuu":["Hỏa Linh Nhi"],"trangThai":"Đang được sử dụng","blurb":"Tấm da quý có khả năng xé rách hư không, giúp người sử dụng di chuyển trên quãng đường dài.","detail":"Hỏa Linh Nhi dùng Hư Không thú bì đưa cả đoàn tới gần Dược Đô. Do khoảng cách quá xa, pháp khí không thể định vị hoàn toàn chính xác nên họ xuất hiện tại một dãy núi gần đích.","nguon":["@c0415"]},{"id":"dan-phuong-to-truyen-cua-thach-hao","name":"Đan phương tổ truyền của Thạch Hạo","cn":"","category":"khac","categoryLabel":"Đan phương","phamCap":"Không nêu","soHuu":["Thạch Hạo"],"trangThai":"Chưa đủ linh dược để sử dụng","blurb":"Đan phương tổ truyền được Thạch Hạo dự định sử dụng nhằm rút ngắn thời gian tiến vào tầng cảnh giới cao hơn.","detail":"Để dùng đan phương và vượt qua cửa ải Liệt Trận Vương cảnh nhanh hơn, Thạch Hạo cần thu thập đủ nhiều loại linh dược. Đây là nguyên nhân hắn quyết định tới Dược Đô.","nguon":["@c0415"]},{"id":"linh-duoc-cay","name":"Linh Dược cây","cn":"","category":"nguyen-lieu","categoryLabel":"Cổ dược Thông Linh","phamCap":"Linh dược hơn năm nghìn năm tuổi","soHuu":[],"trangThai":"Sinh trưởng tại Dược Đô","blurb":"Một linh thảo cổ xưa biến dị thành cây lớn sau khi được lôi kiếp dịch tẩy lễ, sở hữu chiến lực mạnh và khả năng dò xét ác ý.","detail":"Linh Dược cây đứng trên đường lớn trong Dược Đô. Nó dùng hương thơm cùng những cành cây phát sáng để kiểm tra người mới vào thành, phát hiện kẻ mang ác ý với nơi này; trên cây còn kết những nụ hoa quý chỉ đứng sau thánh dược.","nguon":["@c0415"]},{"id":"duoc-dang-hoa-dinh-dong","name":"Dược Đằng hoa đỉnh đồng","cn":"","category":"nguyen-lieu","categoryLabel":"Dược thực Thông Linh","phamCap":"Không nêu","soHuu":[],"trangThai":"Sinh trưởng tại Dược Đô","blurb":"Dược Đằng Thông Linh có những bông hoa mang hình dáng đỉnh đồng xanh, có thể phát lửa và tự luyện thuốc.","detail":"Cây từng hấp thu một đoàn Thần hỏa từ trời rơi xuống rồi xảy ra lột xác. Khi người xếp hàng bỏ dược thảo vào, những bông hoa hình đỉnh đồng của nó có thể trực tiếp chế thuốc thay cho Dược Sư.","nguon":["@c0415"]},{"id":"hoang-kim-duoc-diep","name":"Hoàng Kim Dược Điệp","cn":"","category":"khac","categoryLabel":"Linh trùng","phamCap":"Cá thể không thuần huyết","soHuu":[],"trangThai":"Xuất hiện trong vườn thuốc ngoài Dược Đô","blurb":"Linh trùng quý hiếm có thể thúc đẩy cây thuốc sinh trưởng và hỗ trợ Dược Sư chế thuốc.","detail":"Một cá thể Hoàng Kim Dược Điệp không thuần huyết bay trong vườn thuốc ngoài Dược Đô. Nơi nó đi qua, dược thảo trở nên tràn đầy sinh cơ và hoa nở rộ.","nguon":["@c0415"]},{"id":"thanh-cot-mat-than-tinh","name":"Thánh cốt mất thần tính","cn":"","category":"nguyen-lieu","categoryLabel":"Nguyên liệu","phamCap":"Thánh cốt","soHuu":["A Đức"],"trangThai":"Được bày bán tại Dược đô","blurb":"Khối xương thánh nhân bị rao bán như Chân Long cốt, nhưng phần lớn thần tính đã thất thoát.","detail":"Khối xương chỉ còn một ít thần tính bám ngoài bề mặt. A Đức lợi dụng khí tức còn sót lại để quảng cáo nó là Chân Long cốt và đẩy giá lên cao.","nguon":["@c0416"]},{"id":"mai-rua-trang-chap-va","name":"Mai rùa trắng chắp vá","cn":"","category":"nguyen-lieu","categoryLabel":"Nguyên liệu","phamCap":"Chưa rõ","soHuu":["A Đức"],"trangThai":"Hàng giả được bày bán tại Dược đô","blurb":"Dược liệu giả được ghép từ một mảnh mai rùa trắng quý hiếm với mai rùa thông thường.","detail":"Chỉ một phần nhỏ của vật phẩm là mai rùa trắng, còn những bộ phận khác đều là mai rùa tầm thường được chắp vá nhằm khiến khách mua tưởng toàn bộ là vị thuốc quý.","nguon":["@c0416"]},{"id":"khoi-cot-nghi-chan-hoang-cot","name":"Khối cốt nghi Chân Hoàng cốt","cn":"","category":"nguyen-lieu","categoryLabel":"Bảo cốt · Nguyên liệu","phamCap":"Chưa xác định","soHuu":["Thạch Hạo"],"trangThai":"Đã được Thạch Hạo mua","blurb":"Khối cốt đen lấy từ Thần cốc, bên trong ẩn chứa thần quang và có khả năng là một mảnh Chân Hoàng cốt.","detail":"Khối cốt nằm lẫn trong đống xương và khoáng thạch tại sạp của A Đức. Thạch Hạo dùng Trùng Đồng nhận ra bên trong nó có thần quang như một mặt trời nhỏ nên mua cả đống hàng bằng một bảo cụ Minh Văn cảnh. Tin tức sau đó cho biết các mảnh cốt cùng nguồn có thể lưu giữ phù văn nguyên thủy và sức mạnh bất hủ.","nguon":["@c0416"]},{"id":"co-duoc-than-thanh-tai-than-coc","name":"Cổ dược thần thánh tại Thần cốc","cn":"","category":"nguyen-lieu","categoryLabel":"Nguyên liệu","phamCap":"Thần dược","soHuu":[],"trangThai":"Được trận pháp bảo vệ tại Thần cốc","blurb":"Cổ dược thần thánh được phát hiện tại Thần cốc, trong khu vực rải rác những mảnh xương nghi là Chân Hoàng cốt.","detail":"Cổ dược nằm trong khu vực có trận pháp bảo vệ và được cho là sắp xuất thế. Tin tức về nó cùng Hoàng cốt và thần vật bất hủ đã truyền tới các đại nhân vật tại Dược đô.","nguon":["@c0416"]},{"id":"di-cot-chim-than-cap-thien","name":"Di cốt chim thần cấp Thiên","cn":"","category":"nguyen-lieu","categoryLabel":"Bảo cốt","phamCap":"Cấp Thiên","soHuu":[],"trangThai":"Gần mất sạch tinh hoa thần tính","blurb":"Khối di cốt chim thần được khai quật tại khu vực Thần cốc và đưa cho các đại nhân vật kiểm tra.","detail":"Khối cốt được xác định là di cốt của chim thần cấp Thiên, nhưng không thuộc bộ phận thai nghén phù văn nguyên thủy. Thần tính của nó gần như đã cạn kiệt và chưa đủ để chứng minh đây là Chân Hoàng cốt.","nguon":["@c0417"]},{"id":"phap-khi-do-doa-hoa-thu-hai-ngung-tu","name":"Pháp khí do đóa hoa thứ hai ngưng tụ","cn":"","category":"phap-bao","categoryLabel":"Pháp khí","phamCap":"Chưa rõ","soHuu":[],"trangThai":"Đang biến hóa","blurb":"Pháp khí hình thành từ mưa ánh sáng của đóa hoa thứ hai trên kỳ dược trong Thần cốc.","detail":"Vật này được quầng sáng bao phủ, hình thái liên tục biến đổi giữa dáng tháp, lò và đỉnh. Ngay cả khi vận dụng Trùng Đồng, Thạch Hạo vẫn không thể nhìn rõ hình dạng chân thực của nó.","nguon":["@c0417"]},{"id":"cay-nho-ba-hoa-trong-than-coc","name":"Cây nhỏ ba hoa trong Thần cốc","cn":"","category":"nguyen-lieu","categoryLabel":"Linh căn thiên địa","phamCap":"Ít nhất là linh căn đứng đầu Hoang Vực","soHuu":[],"trangThai":"Bị hơn trăm trận pháp bảo vệ trong Thần cốc","blurb":"Linh căn một cây ba hoa có dị tượng vượt xa thánh dược thông thường, được đánh giá ít nhất là linh căn đứng đầu Hoang Vực.","detail":"Cây nhỏ cao hơn một thước, mang ba đóa hoa đã thông linh. Một đóa có thể hóa thành người tí hon tự tu hành, một đóa khác hóa thành pháp khí phát ra âm thanh giúp thần hồn yên tĩnh, gần đạt trạng thái ngộ đạo, rồi biến thành lò lửa rèn luyện thân thể người tí hon. Sau đó cả người tí hon lẫn pháp khí tan thành mưa sáng và ngưng tụ trở lại thành hoa. Linh căn được bảo vệ bởi hơn trăm trận pháp và có thể không thuộc Hoang Vực hoặc giới này.","nguon":["@c0418"]},{"id":"niet-ban-dan","name":"Niết Bàn đan","cn":"","category":"dan-duoc","categoryLabel":"Đan dược","phamCap":"","soHuu":[],"trangThai":"Chưa được luyện thành do thiếu chủ dược","blurb":"Đan dược cần từ vài chục tới gần một trăm loại linh dược, trong đó có nhiều chủ dược cực kỳ quý hiếm.","detail":"Thạch Hạo tìm mua nguyên liệu để luyện Niết Bàn đan nhằm tăng thực lực, nhưng mới thu thập được bốn mươi tám bảo dược nên chưa thể luyện thành đan dược hoàn chỉnh.","nguon":["@c0418"]},{"id":"duoc-dinh-nghin-nam","name":"Dược đỉnh nghìn năm","cn":"","category":"phap-bao","categoryLabel":"Dược đỉnh","phamCap":"","soHuu":["Chủ nhân đình viện luyện dược"],"trangThai":"Được Thạch Hạo thuê dùng trong ba ngày","blurb":"Chiếc dược đỉnh vàng bóng đã được sử dụng hơn nghìn năm, tích lũy linh tính có khả năng tăng dược hiệu.","detail":"Dược đỉnh đặt trong một đình viện hẻo lánh tại Dược đô, từng được dùng luyện dược suốt hơn một nghìn năm nên tích lũy dược tính và linh tính mạnh mẽ. Thạch Hạo trả ba cây linh dược để thuê đình viện cùng chiếc đỉnh trong ba ngày, chuẩn bị rèn luyện thân thể và khai mở tiềm năng.","nguon":["@c0418"]},{"id":"dia-mach-linh-diem","name":"Địa mạch linh diễm","cn":"","category":"khac","categoryLabel":"Linh hỏa","phamCap":"Linh diễm địa mạch","soHuu":[],"trangThai":"Đang được dẫn lên từ lòng đất Dược đô","blurb":"Ngọn linh diễm màu bạc bắt nguồn từ địa mạch dưới Dược đô, được dùng trong quá trình luyện dược và luyện thân.","detail":"Địa mạch linh diễm được dẫn lên bên dưới dược đỉnh để luyện hóa dược liệu. Khi dược nê hóa thành Kim đan, linh diễm tiếp tục dung nhập, cung cấp vật chất linh tính cho quá trình luyện thân của Thạch Hạo.","nguon":["@c0419"]},{"id":"phuong-thuoc-phu-tro-hoang-toc-thach-quoc","name":"Phương thuốc phụ trợ hoàng tộc Thạch quốc","cn":"","category":"khac","categoryLabel":"Phương thuốc","phamCap":"Một trong những phương thuốc quý giá nhất của hoàng tộc Thạch quốc","soHuu":["Thạch Hạo"],"trangThai":"Đã thất truyền","blurb":"Phương thuốc phụ trợ có thể phối hợp với phương thuốc khác để tăng mạnh dược tính, thậm chí khiến dược liệu biến đổi về chất.","detail":"Phương thuốc không được dùng riêng mà kết hợp với những phương thuốc khác trong quá trình luyện chế. Thạch Hạo vận dụng phương thuốc này cùng pháp ấn, đạo hỏa trong cơ thể và linh diễm bên ngoài để luyện dược, rèn thân và khai mở tiềm năng.","nguon":["@c0419"]},{"id":"duoc-ne-kim-dan","name":"Dược nê Kim đan","cn":"","category":"khac","categoryLabel":"Dược thể","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Đã hình thành trong dược đỉnh","blurb":"Dược thể màu vàng nhạt hình thành từ linh khí và dược liệu cô đặc, bao bọc Thạch Hạo thành hình thái một viên Kim đan.","detail":"Sau khi nước trong dược đỉnh bị sấy khô, linh khí ngưng tụ thành chất lỏng sền sệt rồi hóa thành dược nê bao quanh Thạch Hạo. Dược nê dần chuyển sang màu vàng nhạt, hấp thu linh khí, lôi điện và Địa mạch linh diễm để tạo thành hình thái Kim đan phục vụ quá trình luyện thân.","nguon":["@c0419"]},{"id":"kim-dan","name":"Kim đan","cn":"","category":"dan-duoc","categoryLabel":"Đan dược","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Đã luyện thành; phần lớn dược lực được hấp thu, phần còn lại ngưng tụ thành hai viên","blurb":"Kim đan được luyện từ gần năm mươi gốc linh dược cùng tinh hoa thủy hỏa, giúp tu bổ thân thể và củng cố cảnh giới.","detail":"Kim đan dung hợp tinh hoa thiên địa và hai khí âm dương. Thạch Hạo phá vỡ đan, hấp thu khoảng tám phần dược lực để chữa lành các vết rạn, rèn luyện gân cốt và ổn định Liệt Trận cảnh trung kỳ; hai phần dược lực còn lại được tiếp tục luyện thành hai viên đan.","nguon":["@c0420"]},{"id":"dinh-co-trong-gieng-to","name":"Đỉnh cổ trong giếng tổ","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Không rõ","soHuu":[],"trangThai":"Chìm nổi trong giếng tổ","blurb":"Một chiếc đỉnh cổ nằm sâu trong giếng tổ của Thần Dược môn, chìm nổi như đang được nung nấu.","detail":"Đỉnh cổ xuất hiện trong giếng sâu thông xuống lòng đất tại bí địa giữa Dược đô. Nguồn gốc, chủ nhân và công dụng của nó chưa được tiết lộ.","nguon":["@c0420"]},{"id":"than-an-chi-bao-to-truyen","name":"Thần ấn chí bảo tổ truyền","cn":"","category":"phap-bao","categoryLabel":"Chí bảo","phamCap":"Chí bảo tổ truyền của Bất Lão sơn","soHuu":["Bất Lão sơn"],"trangThai":"Đang được Bất Lão sơn nắm giữ","blurb":"Chí bảo tổ truyền của Bất Lão sơn, có thể đóng thần ấn lên pháp chỉ và giúp mệnh lệnh phá vực mà đi.","detail":"Thần ấn là chí bảo tổ truyền mang tính biểu tượng quyền lực của Bất Lão sơn. Dấu ấn của nó được đóng lên pháp chỉ tìm kiếm đứa trẻ mang một nửa huyết thống Bất Lão sơn; pháp chỉ sau đó phát ra khí tức cổ xưa, phá không rời Huyền Vực và xuyên qua vực bích đã bị phong ấn.","nguon":["@c0422"]},{"id":"phap-chi-dong-than-an","name":"Pháp chỉ đóng thần ấn","cn":"","category":"khac","categoryLabel":"Pháp chỉ","phamCap":"Mang dấu ấn của chí bảo tổ truyền Bất Lão sơn","soHuu":["Bất Lão sơn"],"trangThai":"Đã được phát ra khỏi Huyền Vực","blurb":"Pháp chỉ của Bất Lão sơn được đóng thần ấn, mang mệnh lệnh tìm và nhã nhặn đưa đứa trẻ có một nửa huyết thống của họ trở về.","detail":"Sau cuộc bàn bạc trong đại điện đồng thau, pháp chỉ được khắc dấu thần ấn và gây chấn động khắp Bất Lão sơn. Nó mang hào quang ngập trời phá không rời đi, xuyên qua vực bích đã bị phong ấn để rời Huyền Vực và truyền đạt mệnh lệnh tìm kiếm đứa trẻ.","nguon":["@c0422"]},{"id":"hoang-kim-thao","name":"Hoàng Kim thảo","cn":"","category":"nguyen-lieu","categoryLabel":"Kỳ dược","phamCap":"Kỳ dược","soHuu":["Thạch Hạo"],"trangThai":"Đã đổi chủ","blurb":"Kỳ dược toàn thân vàng óng, cao khoảng một thước và có sáu lá như được khắc từ hoàng kim.","detail":"Hoàng Kim thảo khó nảy mầm nếu thiếu loại linh nê đặc thù. Đây là một trong bốn kỳ dược Lâm Côn giao cho Thạch Hạo và là chủ dược cần thiết để luyện tiểu Niết Bàn đan.","nguon":["@c0423"]},{"id":"lac-nguyet-hoa","name":"Lạc Nguyệt hoa","cn":"","category":"nguyen-lieu","categoryLabel":"Kỳ dược","phamCap":"Kỳ dược","soHuu":["Thạch Hạo"],"trangThai":"Đã đổi chủ","blurb":"Kỳ dược trắng như tuyết, có đóa hoa giống đĩa bạc và tỏa sáng như vầng trăng trong đêm.","detail":"Hương thơm của Lạc Nguyệt hoa khiến lòng người không minh và dễ dàng ngộ đạo. Cây thuốc được Lâm Côn giao cho Thạch Hạo, đồng thời là một chủ dược cần thiết để luyện tiểu Niết Bàn đan.","nguon":["@c0423"]},{"id":"tu-tinh-lan","name":"Tử Tinh lan","cn":"","category":"nguyen-lieu","categoryLabel":"Kỳ dược","phamCap":"Kỳ dược","soHuu":["Thạch Hạo"],"trangThai":"Đã đổi chủ","blurb":"Linh lan màu tím cao bằng lòng bàn tay, có lá mang hình sao sáu cạnh và giá trị cực cao.","detail":"Chỉ một cọng lá Tử Tinh lan đã đủ đổi lấy những linh dược bình thường. Cây thuốc được Thạch Hạo lấy từ vườn thuốc của Lâm Côn và là một trong những chủ dược cần thiết để luyện tiểu Niết Bàn đan.","nguon":["@c0423"]},{"id":"luu-kim-tue-nguyet","name":"Lưu kim tuế nguyệt","cn":"","category":"nguyen-lieu","categoryLabel":"Kỳ dược","phamCap":"Kỳ dược hi thế","soHuu":["Thạch Hạo"],"trangThai":"Đã đổi chủ","blurb":"Kỳ dược hi thế được cho là chỉ còn hai cây tồn tại trên đời, có thể nâng cao phẩm chất đan dược.","detail":"Khi luyện dược, chỉ cần thêm một phần nhỏ Lưu kim tuế nguyệt cũng đủ khiến đan dược mang thêm khí tức đại đạo và tăng mạnh phẩm chất. Cây thuốc được Lâm Côn giao cho Thạch Hạo và là một chủ dược cần thiết để luyện tiểu Niết Bàn đan.","nguon":["@c0423"]},{"id":"hoang-diep","name":"Hoàng điệp","cn":"","category":"khac","categoryLabel":"Thần trùng thái cổ","phamCap":"Thần trùng thái cổ","soHuu":[],"trangThai":"Ấu trùng đang bị phong ấn","blurb":"Thần trùng thái cổ đứng trên Hoàng kim dược điệp, vừa có khả năng tìm kiếm linh dược vừa sở hữu chiến lực đáng sợ.","detail":"Dược thần thời thượng cổ từng đoạt được một ấu trùng Hoàng điệp. Sau khi ông chết, ấu trùng bị phong ấn trong bình Thần Băng và chưa từng xuất thế; theo lời truyền, Hoàng điệp có thể thu hút Hoàng kim dược điệp làm phó điệp bảo vệ mình, thậm chí từng có cá thể rung cánh nghiền nát Liệt thiên ma điệp cấp Thiên Thần.","nguon":["@c0423"]},{"id":"binh-than-bang","name":"Bình Thần Băng","cn":"","category":"phap-bao","categoryLabel":"Vật phong ấn","phamCap":"","soHuu":[],"trangThai":"Đang phong ấn ấu trùng Hoàng điệp","blurb":"Chiếc bình dùng để phong ấn ấu trùng Hoàng điệp từ sau khi Dược thần qua đời. (+) Chiếc bình từng dùng để phong ấn Hoàng điệp. [CAN-SOAT-GOP]","detail":"Bình Thần Băng duy trì trạng thái phong ấn của ấu trùng Hoàng điệp từ thời thượng cổ, khiến sinh linh này chưa từng xuất thế cho tới hiện tại.","nguon":["@c0423","@c0617"],"tabs":{}},{"id":"phap-khi-dong-thau-dan-toi-hoang-diep","name":"Pháp khí đồng thau dẫn tới Hoàng điệp","cn":"","category":"phap-bao","categoryLabel":"Pháp khí","phamCap":"Chưa rõ","soHuu":["Thạch Hạo"],"trangThai":"Một nửa do Thạch Hạo nắm giữ, nửa còn lại đã được phát hiện trong tầng trận pháp thứ ba của Thần cốc","blurb":"Pháp khí gồm hai nửa đồng thau, khắc hơn trăm ký hiệu thần bí và là đầu mối dẫn tới Hoàng điệp trong truyền thuyết.","detail":"Lâm Côn giao một nửa pháp khí cho Thạch Hạo dựa trên ghi chép cổ của Thần Dược môn. Nửa còn lại từng thuộc về con của Dược thần và được Trùng Đồng xác định nằm trong tầng trận pháp thứ ba của Thần cốc, nhưng chưa được lấy ra.","nguon":["@c0424"]},{"id":"the-gioi-hop-bau","name":"Thế giới hộp báu","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo chứa vật","phamCap":"Thái cổ","soHuu":["Thạch Hạo"],"trangThai":"Đã hợp nhất nhưng chưa mở","blurb":"Pháp bảo của các đại nhân vật thời thái cổ, có thể dựng một tiểu thế giới bên trong để cất giữ bảo vật. (+) Pháp bảo không gian được Thạch Hạo chọn mang theo khi rời Thạch thôn. [CAN-SOAT-GOP]","detail":"Vật ban đầu tách thành hai miếng đồng thau, trên mỗi phần có hơn trăm ký hiệu có thể phát sáng và cảm ứng lẫn nhau. Nửa nằm trong trận pháp Thiên Thần chịu sát quang mà không hư hại, sau đó bay ra ghép kín với nửa Thạch Hạo đang giữ thành một vật lớn cỡ nắm tay. Hỏa Linh Nhi và Vân Hi nhận ra đây là Thế giới hộp báu, một vật rất khó bị người ngoài phá hủy hoặc mở ra; nhóm Thạch Hạo đã lần lượt nghiên cứu nhưng chưa thể mở được.","nguon":["@c0425","@c0608"],"tabs":{}},{"id":"trung-hoang-diep","name":"Trứng Hoàng điệp","cn":"","aliases":["Trứng thần trùng"],"category":"khac","categoryLabel":"Vật phẩm","phamCap":"Không rõ","soHuu":[],"trangThai":"Được ấp dưỡng trong địa mạch tổ căn và truyền tống trở lại bình Thần Băng","blurb":"Trứng của Hoàng điệp từng bị phong ấn trong bình Thần Băng, sau đó được Dược thần đưa vào địa mạch tổ căn tại Dược đô để hấp thu tinh hoa thiên địa.","detail":"Dược thần phát hiện quả trứng bị phong ấn trong bình Thần Băng và bố trí cho nó được ấp dưỡng bằng lượng tinh hoa thiên địa dồi dào tại địa mạch tổ căn. Khi quá trình ấp dưỡng hoàn tất, trận pháp sẽ đưa trứng trở lại bình để tiếp tục phong ấn.","nguon":["@c0426"]},{"id":"bat-lao-tuyen","name":"Bất Lão Tuyền","cn":"","category":"nguyen-lieu","categoryLabel":"Thần dịch","phamCap":"Thần dịch cứu mạng","soHuu":["Thạch Hạo"],"trangThai":"Còn hai giọt, được phong ấn riêng trong cầu thủy tinh","blurb":"Thần dịch do Thạch Hạo từng lấy được tại Bách Đoạn sơn và mang về cho Thạch thôn. Hai giọt được dùng trong quá trình cứu chữa cậu. (+) Thần dịch cực kỳ hiếm, có khả năng cải tử hồi sinh khi tính mạng lâm nguy. [CAN-SOAT-GOP] (+) Bất lão tuyền từng được dùng để cứu Thạch Hạo khi hắn hấp hối. Tinh hoa còn tích trữ trong máu thịt góp phần bổ sung sinh cơ và chống lại nguyền rủa. [CAN-SOAT-GOP]","detail":"Thạch Hạo từng thu được năm giọt tại Bách Đoạn sơn, nhưng hiện chỉ còn hai giọt được phong ấn riêng. Hoàng điệp tỏ ra say mê và đánh dấu chúng nhưng chưa hấp thu.","nguon":["@c0428","@c0597","@c0604"],"tabs":{}},{"id":"ruou-thai-co-tu-to-con-bang","name":"Rượu thái cổ từ tổ Côn Bằng","cn":"","category":"khac","categoryLabel":"Thần tửu","phamCap":"Thần tửu hiếm có","soHuu":["Thạch Hạo"],"trangThai":"Hoàng điệp đã hấp thu một giọt","blurb":"Rượu thái cổ lấy từ tổ Côn Bằng, có tác dụng bồi bổ mạnh hơn nhiều loại dược liệu.","detail":"Rượu được cất trong một bầu rượu nằm trong túi Càn Khôn của Thạch Hạo. Hoàng điệp chui vào trong và hấp thu một giọt để bổ sung dưỡng chất sau khi xuất thế.","nguon":["@c0428"]},{"id":"canh-lieu-bao-menh","name":"Cành liễu bảo mệnh","cn":"","category":"khac","categoryLabel":"Vật bảo mệnh","phamCap":"Vật do Liễu Thần ban","soHuu":["Thạch Hạo"],"trangThai":"Bị Hoàng điệp ăn mất ba chồi non","blurb":"Cành cây do Liễu Thần ban cho Thạch Hạo, có thể giúp hắn tránh khỏi một kiếp khi gặp nguy hiểm.","detail":"Cành liễu được niêm phong trong hộp đá và đi kèm một đoạn thần chú dùng lúc nguy cấp. Hoàng điệp tự mở hộp, ôm chặt cành cây rồi ăn ba chồi non để củng cố thần tinh trời sinh trước khi chìm vào giấc ngủ.","nguon":["@c0428"]},{"id":"phap-chi-bat-lao-son","name":"Pháp chỉ Bất Lão sơn","cn":"","category":"phap-bao","categoryLabel":"Pháp chỉ","phamCap":"Không rõ","soHuu":["Người trung niên giữ pháp chỉ"],"trangThai":"Hoàn chỉnh, đã giáng xuống Hoang Vực","blurb":"Pháp chỉ màu vàng của Bất Lão sơn có thể xuyên qua vực bích, truyền hiệu lệnh triệu kiến Thạch Hạo.","detail":"Pháp chỉ từ vực ngoài xuyên thủng vực bích và giáng xuống hoàng đô Hỏa quốc, tỏa kim quang, hiện các ký hiệu đại đạo và có dấu hiệu niêm phong một vùng thế giới. Người của Bất Lão sơn dùng nó để truyền lệnh, thúc ép và uy hiếp Thạch Hạo tới yết kiến.","nguon":["@c0429"]},{"id":"linh-vu-do-dam-cua-tieu-hong","name":"Linh vũ đỏ đậm của Tiểu Hồng","cn":"","category":"khac","categoryLabel":"Tín vật","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Được phong ấn trong hộp đá","blurb":"Một cọng linh vũ màu đỏ đậm do Tiểu Hồng lưu lại, được dùng làm tín vật liên hệ Tế Linh Hỏa quốc.","detail":"Linh vũ được phong ấn trong hộp đá. Thạch Hạo giao tín vật này khi nhờ Hỏa Linh Nhi đưa Đại Hồng Điểu tới tổ địa Hỏa quốc gặp Tiểu Hồng.","nguon":["@c0429"]},{"id":"doa-hoa-linh-duoc-ngoai-cua-duoc-do","name":"Đóa hoa Linh Dược ngoài cửa Dược Đô","cn":"","category":"nguyen-lieu","categoryLabel":"Linh dược","phamCap":"Linh Dược, cây mẹ sắp tiến hóa thành Thánh Dược","soHuu":["Thạch Hạo"],"trangThai":"Được Môn chủ Đan Đỉnh Giáo tặng cho Thạch Hạo","blurb":"Đóa hoa quý lấy từ cây Linh Dược ngoài cửa Dược Đô, mang dược lực khiến tinh khí dồi dào.","detail":"Cây mẹ từng hấp thu Lôi Kiếp dịch, đã sống mấy nghìn năm và không bao lâu nữa sẽ tiến hóa thành Thánh Dược. Môn chủ Đan Đỉnh Giáo đem đóa hoa tặng Thạch Hạo khi hắn chuẩn bị rời Dược Đô.","nguon":["@c0430"]},{"id":"cuu-chuyen-than-dan","name":"Cửu Chuyển Thần Đan","cn":"","category":"dan-duoc","categoryLabel":"Thần đan","phamCap":"Thần đan","soHuu":[],"trangThai":"Chỉ được nhắc trong truyền thuyết của Đan Đỉnh Môn","blurb":"Thần đan được truyền rằng có thể khiến người uống lập tức thành Thần, nhưng hạ giới hàng chục vạn năm cũng khó xuất hiện một lò. (+) Thần đan hiếm có mà từ xưa được kể rằng chỉ bốn người từng luyện thành. [CAN-SOAT-GOP]","detail":"Thủy tổ Đan Đỉnh Môn là một trong bốn người được truyền lại là từng luyện thành Cửu Chuyển Thần Đan. Theo lời kể, vị thủy tổ sau khi dùng thần đan đã thành Thần và phi thăng lên trời.","nguon":["@c0430","@c0598"]},{"id":"duoc-dan-do-hoa-kim-dang-luyen-che","name":"Dược đan do Hỏa Kim Đằng luyện chế","cn":"","category":"dan-duoc","categoryLabel":"Đan dược","phamCap":"","soHuu":["Hỏa Nha"],"trangThai":"Đã luyện thành","blurb":"Dược đan được Hỏa Kim Đằng luyện từ dược thảo do Hỏa Nha mang tới, có linh tính dồi dào và phẩm chất vượt trội.","detail":"Hỏa Kim Đằng hấp thu kim loại hiếm làm thù lao rồi dùng Thần Hỏa trong hoa đỉnh đồng thau để luyện dược. Thành phẩm có linh tính mười phần và tốt hơn rõ rệt so với đan dược do những người luyện chế thông thường tạo ra.","nguon":["@c0416"]},{"id":"ho-ti-cua-van-hi","name":"Hộ tí của Vân Hi","cn":"","category":"khac","categoryLabel":"Vật phẩm","phamCap":"Chưa rõ","soHuu":["Vân Hi"],"trangThai":"Thạch Hạo đang giữ; Vân Hi yêu cầu hoàn trả","blurb":"Vật phẩm rất quan trọng đối với Vân Hi và kế hoạch của Thiên Nhân tộc.","detail":"Vân Hi đề nghị Thạch Hạo trả lại hộ tí, đồng thời mời nó cùng tộc nhân theo Thiên Nhân tộc rời khỏi đại vực bằng trận pháp thái cổ.","nguon":["@c0431"]},{"id":"canh-thit-viem-mang-thuan-huyet","name":"Canh thịt Viêm Mãng thuần huyết","cn":"","category":"dan-duoc","categoryLabel":"Bảo dược, món ăn","phamCap":"Bảo dược thuần huyết","soHuu":["Thạch Hạo"],"trangThai":"Được dùng trong tiệc tại Thạch thôn","blurb":"Món canh do Thạch Hạo chế biến từ thịt Viêm Mãng thuần huyết, chứa dược lực mạnh và có tác dụng bồi bổ.","detail":"Dược lực của món canh khiến đám trẻ Thạch thôn sau khi ăn phải chạy khắp thôn suốt đêm để tiêu hao. Việc hấp thu dược lực cũng mang lại lợi ích, có thể giúp chúng nhanh chóng đột phá cảnh giới.","nguon":["@c0434"]},{"id":"tran-do-tu-bo-co-tran","name":"Trận đồ tu bổ cổ trận","cn":"","category":"khac","categoryLabel":"Trận đồ","phamCap":"Không rõ","soHuu":["Nhị Ngốc Tử"],"trangThai":"Đang được dùng để đối chiếu cổ trận","blurb":"Trận đồ Nhị Ngốc Tử chiếm được từ thuở nhỏ, ghi lại những bộ phận có thể bổ khuyết cổ trận vượt giới của Thiên Thần Sơn.","detail":"Khi kiểm tra cổ trận đã hư hại, Nhị Ngốc Tử đối chiếu nó với trận đồ này và xác nhận các bộ phận được ghi chép vừa khéo có thể dùng để sửa chữa những phần bị thiếu.","nguon":["@c0436"]},{"id":"than-lieu-tu-bo-co-tran","name":"Thần liệu tu bổ cổ trận","cn":"","category":"nguyen-lieu","categoryLabel":"Nguyên liệu","phamCap":"Thần liệu quý hiếm","soHuu":[],"trangThai":"Chưa thu thập đủ","blurb":"Hơn chục loại vật liệu quý hiếm cần thiết để khôi phục cổ trận vượt giới của Thiên Thần Sơn.","detail":"Danh sách thần liệu do Nhị Ngốc Tử viết ra có mức tiêu hao rất lớn. Bảo khố Thiên Thần Sơn tích lũy nhiều năm vẫn không thể gom đủ, trong đó có vài loại hoàn toàn không có, khiến Vân Thương Hải phải tính chuyện hợp tác với một Thần sơn khác.","nguon":["@c0436"]},{"id":"co-xanh-sao-den","name":"Cờ xanh sao đen","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Pháp khí Thần Linh","soHuu":["Vân Kim Hải"],"trangThai":"Đang được sử dụng","blurb":"Lá cờ cổ có cán kim loại xanh và một ngôi sao đen, đủ uy lực giết chết Tôn giả.","detail":"Vân Kim Hải dùng lá cờ để tấn công Khổng Cầu Kỷ. Pháp khí có thể phóng ra vô tận kiếm khí và lôi đình màu xanh, tạo uy áp khiến Tôn giả sợ hãi, nhưng các đòn công kích trong trận này đều không thể tới gần mục tiêu.","nguon":["@c0438"]},{"id":"duong-thach","name":"Dương thạch","cn":"","category":"nguyen-lieu","categoryLabel":"Nguyên liệu","phamCap":"Thần liệu","soHuu":["Kim Sí Đại Bằng tộc"],"trangThai":"Được mang tới Thiên Thần sơn","blurb":"Khối thần liệu hừng hực như lửa, thuộc số vật liệu dùng để tu bổ trận pháp vượt giới.","detail":"Dương thạch là một trong năm loại thần liệu được Kim Sí Đại Bằng tộc lấy từ bảo khố và mang tới Thiên Thần sơn, góp vào hơn mười loại vật liệu cần thiết để sửa chữa trận pháp do Thần Thánh thời Thái cổ lưu lại.","nguon":["@c0438"]},{"id":"long-huyet-tho","name":"Long Huyết Thổ","cn":"","category":"nguyen-lieu","categoryLabel":"Nguyên liệu","phamCap":"Thần liệu","soHuu":["Kim Sí Đại Bằng tộc"],"trangThai":"Được mang tới Thiên Thần sơn","blurb":"Thần liệu đỏ rực như lửa, được dùng trong việc tu bổ trận pháp vượt giới.","detail":"Long Huyết Thổ là một trong năm loại thần liệu được Kim Sí Đại Bằng tộc lấy từ bảo khố và mang đến hỗ trợ Thiên Thần sơn sửa chữa trận pháp do Thần Thánh thời Thái cổ lưu lại.","nguon":["@c0438"]},{"id":"phap-khi-than-linh-cua-thien-than-son","name":"Pháp khí Thần Linh của Thiên Thần sơn","cn":"","category":"than-khi","categoryLabel":"Pháp khí Thần Linh","phamCap":"Thần Linh","soHuu":["Thiên Thần sơn"],"trangThai":"Đã được hoàn trả cho Thiên Thần sơn","blurb":"Pháp khí của Thiên Thần sơn từng do Thạch Hạo giữ, sau đó được chủ động trao trả cho Vân Thương Hải.","detail":"Thạch Hạo mang pháp khí này trả lại cho phía Thiên Thần sơn trước khi đề nghị các cường tộc cung cấp thần liệu để sửa chữa trận pháp trong thôn.","nguon":["@c0440"]},{"id":"tui-can-khon-cua-thach-hao","name":"Túi càn khôn","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo chứa đồ","phamCap":"Không nêu","soHuu":["Thạch Hạo"],"trangThai":"Đang được sử dụng","blurb":"Túi chứa đồ được Thạch Hạo dùng để thu gom thần liệu của các đại tộc.","detail":"Thạch Hạo lấy túi càn khôn ra và thu gần một nửa số thần liệu có tại chỗ, khiến những lão giả trông coi vật liệu phải ra tay ngăn cản.","nguon":["@c0440"]},{"id":"nguyen-thuy-chan-vu-kim-si-dai-bang","name":"Nguyên thủy Chân vũ của Kim Sí Đại Bằng tộc","cn":"","category":"nguyen-lieu","categoryLabel":"Thần liệu","phamCap":"Không nêu","soHuu":["Kim Sí Đại Bằng tộc"],"trangThai":"Đang được Thạch Hạo yêu cầu cung cấp","blurb":"Một cọng chân vũ nguyên thủy của Kim Sí Đại Bằng tộc được yêu cầu làm nguyên liệu tế luyện Quạt Ngũ Cầm.","detail":"Thạch Hạo viện danh vị đại nhân đứng sau mình để yêu cầu phía Bằng tộc cung cấp một cọng nguyên thủy Chân vũ. Yêu cầu này khiến Kim Loạn Thiên vô cùng tức giận.","nguon":["@c0440"]},{"id":"khuyen-tai-linh-te","name":"Khuyên tai Linh Tê","cn":"","category":"khac","categoryLabel":"Tín vật đính ước","phamCap":"","soHuu":["Thạch Hạo"],"trangThai":"Đang ở trong tay Thạch Hạo","blurb":"Tín vật đính ước của nữ tử Thiên Nhân tộc sau khi trưởng thành, gắn với hôn ước giữa Vân Hi và Thạch Hạo.","detail":"Khuyên tai Linh Tê của Vân Hi từng bị Thạch Hạo lấy đi. Khi biết tín vật đang ở trong tay Thạch Hạo, Vân Mộng Lan cho phép nó sau này tới cầu thân Vân Hi.","nguon":["@c0441"]},{"id":"canh-lieu-vang-kim","name":"Cành liễu vàng kim","cn":"","category":"khac","categoryLabel":"Tín vật","phamCap":"","soHuu":["Nhị Ngốc Tử","Vân Mộng Lan"],"trangThai":"Được Liễu Thần ban tặng","blurb":"Cành liễu màu vàng kim đặc biệt được Liễu Thần ban cho Nhị Ngốc Tử và Vân Mộng Lan.","detail":"Liễu Thần tặng cành liễu vàng kim khi tác hợp cho Nhị Ngốc Tử và Vân Mộng Lan, đồng thời cho Nhị Ngốc Tử cơ hội đưa một người trở lại Thạch thôn trước khi trận pháp mở ra.","nguon":["@c0441"]},{"id":"phap-ban-hon-don","name":"Pháp bàn Hỗn Độn","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Chưa rõ","soHuu":["Chàng trai thần bí nắm giữ pháp bàn Hỗn Độn"],"trangThai":"Được mang tới Đại Hoang để tìm kiếm Thần tàng Chí Tôn","blurb":"Pháp bảo do một chàng trai thần bí nắm giữ khi tới Đại Hoang tìm kiếm Thần tàng Chí Tôn.","detail":"Công năng và phẩm cấp của Pháp bàn Hỗn Độn chưa được hé lộ. Vật này được nhắc đến cùng chủ nhân trong số những cường giả vực ngoại từng truy tìm Thần tàng Chí Tôn tại Đại Hoang.","nguon":["@c0442"]},{"id":"lam-hai-xuyen","name":"Lam Hải xuyên","cn":"","category":"nguyen-lieu","categoryLabel":"Nguyên liệu","phamCap":"Thần liệu","soHuu":["Thạch Hạo"],"trangThai":"Đã được dùng để bố trí đại trận bảo hộ Thạch thôn","blurb":"Thần liệu trong suốt óng ánh, tỏa ra khí tức đại dương, thuộc số vật liệu quý Thạch Hạo mang về Thạch thôn.","detail":"Lam Hải xuyên là một trong hơn mười loại thần liệu được Thạch Hạo giao cho Liễu Thần. Liễu Thần sử dụng số thần liệu này để hoàn thành đại trận kết hợp phòng ngự, tiến công và truyền tống cho Thạch thôn.","nguon":["@c0442"]},{"id":"chuong-co-than-bi","name":"Chuông cổ thần bí","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Chưa rõ","soHuu":[],"trangThai":"Đã giáng xuống Hoang Vực","blurb":"Một chiếc chuông cổ từ khe trời hạ xuống Hoang Vực, phát ra tiếng chuông truyền khắp toàn vực.","detail":"Chuông xuất hiện từ khe trời giống miệng núi lửa lộn ngược giữa lúc pháp tắc ngoại giới tràn xuống. Tiếng chuông tạo thành những gợn sóng có thể nhìn thấy, bao trùm Đại Hoang; không gian quanh nó vặn vẹo, tiên quang và điềm lành lan tỏa. Những ký hiệu trên thân chuông cộng hưởng thành tế văn như lời chiếu cáo chúng sinh, khiến Tiểu Tháp kinh ngạc khi nhận ra vật này.","nguon":["@c0443"]},{"id":"chuong-lon-bi-an","name":"Chuông lớn bí ẩn","cn":"","category":"phap-bao","categoryLabel":"Pháp khí","phamCap":"","soHuu":[],"trangThai":"Xuất hiện tại Hoang Vực","blurb":"Một trong ba pháp khí xuất hiện để dò xét những tồn tại siêu nhiên trong Hoang Vực.","detail":"Chuông lớn xuất hiện từ miệng núi lửa lộn ngược. Khi chuông ngân vang, gợn sóng khuếch tán khiến thiên địa đại đạo nổ vang như tế văn được ngâm tụng; nó cùng thân tháp hai tầng và khay Hỗn Độn không trọn vẹn dò xét toàn vực.","nguon":["@c0444"]},{"id":"khay-hon-don-khong-tron-ven","name":"Khay Hỗn Độn không trọn vẹn","cn":"","category":"phap-bao","categoryLabel":"Pháp khí","phamCap":"","soHuu":[],"trangThai":"Chỉ còn khoảng một phần ba","blurb":"Mảnh pháp khí từ Thượng giới, bị mất khoảng hai phần ba và khác với mảnh từng do thiếu niên trong lửa thần nắm giữ.","detail":"Khi khay xuất hiện, đông đảo sinh linh có cảm giác như đã trải qua nhiều kiếp. Nó cùng hai pháp khí khác dò xét Hoang Vực, phát ra những gợn sóng đan xen như muốn giam giữ toàn vực và tìm kiếm các tồn tại siêu nhiên.","nguon":["@c0444"]},{"id":"ba-phap-khi-dai-kiep","name":"Ba pháp khí đại kiếp","cn":"","category":"phap-bao","categoryLabel":"Pháp khí","phamCap":"","soHuu":[],"trangThai":"Đang hoạt động","blurb":"Ba pháp khí lơ lửng trên trời cao trong đại kiếp, phát tán gợn sóng trấn áp vạn vật và phối hợp truy bắt cường giả đỉnh cao.","detail":"Ba pháp khí trở nên mơ hồ nhưng không biến mất, tiếp tục treo trên trời cao và phối hợp với xích thần trật tự để khóa, trấn áp và truy bắt các Tôn giả cùng cường giả ẩn mình trong Hoang Vực.","nguon":["@c0445"]},{"id":"luoi-dao-than-quy-tac","name":"Lưỡi đao thần quy tắc","cn":"","category":"phap-bao","categoryLabel":"Pháp khí","phamCap":"","soHuu":[],"trangThai":"Đang hoạt động","blurb":"Lưỡi đao trong suốt do quy tắc hình thành, có thể phá tan sự chống cự và chém đầu một giả Thần đã có chút Thần Hỏa.","detail":"Lưỡi đao từ trên cao hạ xuống chặn đường sống của giả Thần có ánh đỏ. Nó phá tan phù văn chống cự, chém lìa đầu đối phương và đánh đổ Pháp tướng khổng lồ.","nguon":["@c0445"]},{"id":"thanh-mau-mau-den","name":"Thanh mâu màu đen","cn":"","category":"phap-bao","categoryLabel":"Pháp khí","phamCap":"","soHuu":[],"trangThai":"Đang hoạt động","blurb":"Thanh mâu đen sắc bén lao xuống từ trời cao, xuyên giết một Tôn giả và cuốn thi thể đi.","detail":"Thanh mâu tuy không dài nhưng có tốc độ và uy lực đáng sợ. Nó xuyên thủng ông lão Tôn giả, cuốn xác đi xa; dư lực từ đòn đánh còn khiến thiếu nữ áo trắng đứng gần đó nổ tung.","nguon":["@c0445"]},{"id":"ngoc-kiem-cua-nguyet-thien","name":"Ngọc Kiếm của Nguyệt Thiền","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Chưa rõ","soHuu":["Nguyệt Thiền tiên tử"],"trangThai":"Được đặt lại trên bàn đá trong tiểu thế giới","blurb":"Thanh kiếm bằng ngọc được Nguyệt Thiền dùng để phá tràng vực mười Động Thiên của Thạch Hạo. (+) Thanh ngọc kiếm được Nguyệt Thiền dùng để đâm xuyên ngực Thạch Hạo. [CAN-SOAT-GOP]","detail":"Khi bị tràng vực của Thạch Hạo khiến không gian và vạn vật xung quanh bất động, Nguyệt Thiền cầm Ngọc Kiếm nhẹ nhàng rạch một phát, phá vỡ tràng vực và thoát khỏi sự trấn áp.","nguon":["@c0448","@c0464","@c0672"],"tabs":{}},{"id":"do-nhai-dao-thu-nui-than","name":"Đồ nhái Đạo thư núi thần","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Được gia trì một phần khí thế Thần Linh","soHuu":["Đạo sĩ trung niên bảo vệ sơn môn Bổ Thiên giáo"],"trangThai":"Đã bị phá hủy","blurb":"Bản mô phỏng Đạo thư núi thần, có thể dựng trận khí tím, trấn áp đối thủ và ăn mòn pháp bảo.","detail":"Đạo sĩ trung niên dùng quyển sách dựng trận phong tỏa Thạch Hạo. Nó phá chiến mâu màu xanh, đánh vỡ Đồng ấn cấp Vương và sau khi hấp thu tinh huyết của đạo sĩ thì bộc phát khí tức Thần Linh, nhưng lập tức bị long khí từ hoàng cung Thạch Quốc đánh thành bột mịn.","nguon":["@c0449"]},{"id":"dao-thu-nui-than","name":"Đạo thư núi thần","cn":"","category":"than-khi","categoryLabel":"Thần khí","phamCap":"Pháp khí Thần Linh","soHuu":["Núi thần tím"],"trangThai":"Được truyền lại cho môn phái của núi thần tím","blurb":"Sách quý nguyên bản do núi tím đã thông linh thành thần dùng nhau thai của mình tế luyện.","detail":"Núi thần tím ở bên ngoài Bổ Thiên giáo dùng nhau thai tế luyện thành quyển sách quý rồi truyền lại trước khi rời đi khai phái. Quyển Đạo thư được đạo sĩ dùng để ngăn Thạch Hạo chỉ là đồ nhái, không phải pháp khí nguyên bản này.","nguon":["@c0449"]},{"id":"dong-an-cap-vuong","name":"Đồng ấn cấp Vương","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Cấp Vương","soHuu":["Nhóm huynh đệ già của Thập Ngũ gia"],"trangThai":"Đã bị phá hủy","blurb":"Một chiếc Đồng ấn cấp Vương có thể hóa lớn như núi, được dùng để công phá trận khí tím đang vây Thạch Hạo.","detail":"Một người trong nhóm viện binh của phủ Hoang Thiên hầu phóng Đồng ấn vào trận pháp. Pháp bảo bị Đồ nhái Đạo thư núi thần đánh vỡ, bùng phát ánh sáng chói lọi rồi hóa thành bột mịn.","nguon":["@c0449"]},{"id":"phap-tien-hoang-cung-thach-quoc","name":"Pháp tiễn hoàng cung Thạch Quốc","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo quân dụng","phamCap":"Không rõ","soHuu":["Quân giữ hoàng cung Thạch Quốc"],"trangThai":"Đã được giương lên để ngăn Thạch Hạo","blurb":"Pháp tiễn quân dụng được chế tạo chuyên biệt để đối phó những người có tu vi cao thâm.","detail":"Theo lệnh của chiến tướng giữ tường thành, quân giữ hoàng cung đồng loạt giương loại pháp tiễn này khi Thạch Hạo yêu cầu vào cung. Cuộc công kích chưa diễn ra vì chiếu thư của Thạch Hoàng được mang tới tuyên đọc.","nguon":["@c0449"]},{"id":"chieu-thu-cua-thach-hoang-danh-cho-thach-hao","name":"Chiếu thư của Thạch Hoàng dành cho Thạch Hạo","cn":"","category":"khac","categoryLabel":"Chiếu thư","phamCap":"Không áp dụng","soHuu":["Thị vệ mang chiếu thư của Thạch Hoàng"],"trangThai":"Đã được công khai tuyên đọc","blurb":"Chiếu thư quy định rằng khi Thạch Hạo xuất hiện, quân giữ cung phải cho phép nó tiến vào hoàng cung Thạch Quốc.","detail":"Mệnh lệnh từng bị chiến tướng giữ tường thành phủ nhận, dù người của phủ Hoang Thiên hầu đã biết nội dung. Một thị vệ sau đó mang chiếu thư lên tường thành và tuyên đọc trước mọi người, buộc chiến tướng cùng quân lính phải lui sâu vào hoàng cung.","nguon":["@c0449"]},{"id":"ho-lo-mau","name":"Hồ lô máu","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Thánh khí","soHuu":["Phe phủ Hoang Thiên hầu"],"trangThai":"Đã bị phong ấn và xóa ấn ký chủ nhân cũ","blurb":"Một Thánh khí có thể phóng ánh kiếm tập kích đối thủ, ban đầu do chiến tướng trấn giữ cửa cung sử dụng.","detail":"Hồ lô máu phóng ánh kiếm tập kích Thạch Hạo nhưng bị thần quang từ Chí Tôn cốt áp chế và đánh ngược. Thạch Hạo phong ấn pháp bảo, xóa ấn ký chủ nhân rồi giao cho một lão nhân của phủ Hoang Thiên hầu; sau đó nó được dùng để uy hiếp Tần Dũng.","nguon":["@c0450"]},{"id":"kim-gian-bo-thien-giao","name":"Kim giản","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Thánh khí","soHuu":["Thanh niên cầm kim giản"],"trangThai":"Đang được sử dụng","blurb":"Thánh khí do kỳ tài Bổ Thiên giáo mang theo để ngăn cản Thạch Hạo.","detail":"Kim giản tỏa ra từng luồng sương trắng và mang khí tức khủng bố. Người sử dụng cầm nó chắn phía trước khi cuộc đối đầu với Thạch Hạo sắp bùng nổ.","nguon":["@c0451"]},{"id":"binh-bat-cua-thanh-nien-tay-thien-giao","name":"Bình bát của thanh niên Tây Thiên giáo","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Thánh khí","soHuu":["Thanh niên tóc ngắn cầm bình bát"],"trangThai":"Đang được sử dụng","blurb":"Thánh khí của thanh niên Tây Thiên giáo, được dùng để chặn đường Thạch Hạo.","detail":"Bình bát tỏa ra từng luồng tử khí, phủ kín khu vực phía trước người sử dụng. Nó cùng kim giản của kỳ tài Bổ Thiên giáo tạo thành thế ngăn cản Thạch Hạo trong trung ương Thiên cung.","nguon":["@c0451"]},{"id":"lenh-bai-to-truyen-cua-con-vuong","name":"Lệnh bài tổ truyền của Côn vương","cn":"","category":"phap-bao","categoryLabel":"Pháp khí","phamCap":"Không rõ","soHuu":["Côn vương"],"trangThai":"Đã bị phá hủy","blurb":"Pháp khí được Côn vương tế luyện nhiều năm, có thể tương thông tâm thần với chủ nhân.","detail":"Côn vương dùng lệnh bài chống lại chuỗi sét hình cầu của Thạch Hạo. Pháp khí xuất hiện nhiều vết nứt dưới đòn đánh rồi hóa thành bột mịn, đồng thời khiến Côn vương chịu phản chấn và bị thương nặng.","nguon":["@c0452"]},{"id":"ngoc-ty-thach-quoc","name":"Ngọc tỷ Thạch quốc","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Đại ấn quốc vận","soHuu":["Thạch quốc"],"trangThai":"Vỡ nát","blurb":"Đại ấn đại diện cho số mệnh Thạch quốc, được phát hiện đã vỡ nát trên bảo tọa Nhân Hoàng.","detail":"Ngọc tỷ là biểu tượng gắn với quốc vận và trung tâm quyền lực của Thạch quốc. Việc nó vỡ nát cho thấy Trung Ương Thiên Cung từng hứng chịu một cuộc công kích nghiêm trọng trong đại kiếp.","nguon":["@c0453"]},{"id":"phap-chi-truyen-ngoi","name":"Pháp chỉ truyền ngôi","cn":"","category":"phap-bao","categoryLabel":"Pháp chỉ","phamCap":"","soHuu":["Thạch Hoàng"],"trangThai":"Đã công bố","blurb":"Pháp chỉ màu vàng công bố việc truyền ngôi cho Thạch Hạo, truyền âm khắp Thạch đô và hội tụ bí lực từ sự hưởng ứng của dân chúng.","detail":"Pháp chỉ truyền lời lập Thạch Hạo làm tân hoàng đế. Khi dân chúng quỳ lạy và tung hô Nhân Hoàng, pháp chỉ càng thêm óng ánh, ngưng tụ bí lực Hoàng đạo để gia trì cho người kế vị.","nguon":["@c0455"]},{"id":"than-an-quoc-bao-thach-quoc","name":"Thần ấn quốc bảo Thạch Quốc","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Quốc bảo","soHuu":["Thạch Hạo"],"trangThai":"Đang gia trì tân Nhân Hoàng","blurb":"Quốc bảo Thạch Quốc gia trì cho Thạch Hạo khi hắn kế thừa ngôi vị hoàng đế.","detail":"Thần ấn hòa cùng khí vận thiên địa của Thạch Quốc để gia trì Thạch Hạo trong quá trình tiếp nhận ngôi vị, góp phần củng cố uy thế của tân Nhân Hoàng.","nguon":["@c0456"]},{"id":"du-lon-mau-den","name":"Dù lớn màu đen","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Thánh khí","soHuu":[],"trangThai":"Đang được sử dụng","blurb":"Một thánh khí lưu chuyển thánh quang, được nhiều cường giả hợp sức điều khiển để vây công Thạch Hạo.","detail":"Dù lớn màu đen phối hợp với kim giản và bình bát tạo thành thế vây công. Khi được nhiều cường giả cùng điều khiển, nó lưu chuyển thánh quang và bộc lộ sức mạnh rất lớn.","nguon":["@c0458"]},{"id":"quan-the-bao-dien-hoang-cung","name":"Quần thể bảo điện hoàng cung","cn":"","category":"khac","categoryLabel":"Vật phẩm khác","phamCap":"Chưa rõ","soHuu":[],"trangThai":"Đang hoạt động","blurb":"Quần thể cung điện có thể phát sáng, cộng hưởng với long khí Hoàng đạo và quấy nhiễu việc điều khiển thánh khí.","detail":"Khi long khí Hoàng đạo trên người Thạch Hạo sôi trào, các bảo điện đồng loạt phát sáng, cắt đứt cảm ứng giữa tu sĩ ba giáo và ba thánh khí đang vây công. Toàn bộ hoàng cung sau đó còn tự động sinh ra liên hệ với Thạch Hạo như một vật có sinh mệnh.","nguon":["@c0458"]},{"id":"mieng-dong-thau","name":"Miếng đồng thau","cn":"","category":"khac","categoryLabel":"Vật phẩm","phamCap":"Chưa rõ","soHuu":[],"trangThai":"Nguyên vẹn, đã mở thông đạo màu vàng","blurb":"Một miếng đồng thau còn nguyên sau khi khu vực bị Lục Thần trận oanh kích suốt một canh giờ.","detail":"Miếng đồng thau được Nguyệt Thiền tiên tử phát hiện giữa vùng đất cháy đen do lôi điện cày nát. Vật này bất ngờ phát sáng, mở một thông đạo màu vàng tới ngay trước người nàng; một bàn tay lớn từ trong thông đạo vươn ra, chụp lấy eo nàng rồi kéo về phía sau.","nguon":["@c0459"]},{"id":"hoang-an","name":"Hoàng ấn","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Không rõ","soHuu":["Thạch Hạo"],"trangThai":"Đang được sử dụng","blurb":"Pháp ấn trong suốt có khả năng mở nội khố hoàng gia.","detail":"Thạch Hạo đặt Hoàng ấn lên cửa đá, kích hoạt hệ thống phù văn phức tạp và mở lối vào nội khố hoàng gia.","nguon":["@c0462"]},{"id":"bon-phap-kiem-than-linh","name":"Bốn pháp kiếm Thần Linh","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Pháp khí Thần Linh","soHuu":["Thạch Hạo"],"trangThai":"Được cất giữ trong nội khố hoàng gia","blurb":"Bộ bốn cổ kiếm có kiểu dáng khác nhau, sở hữu khí thế và độ sắc bén kinh người.","detail":"Bốn pháp kiếm do hậu thế thu gom rồi phong tồn trong nội khố hoàng gia. Thạch Hạo dự định treo chúng trước cửa hoàng cung và bố trí một trận pháp siêu cấp tương ứng để tăng cường khả năng phòng vệ.","nguon":["@c0462"]},{"id":"chien-kich-phong-thien-hoang","name":"Chiến kích phỏng Thiên Hoang","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Pháp khí Thần Linh","soHuu":["Thạch Hạo"],"trangThai":"Đã được Thạch Hạo lấy khỏi nội khố","blurb":"Chiến kích Thần Linh do một đại năng Thượng cổ luyện chế dựa theo kích Thiên Hoang của Côn Bằng.","detail":"Cây chiến kích có thân màu đen, bề ngoài không phát sáng, nhưng khi được khống chế có thể bùng lên ánh vàng ngút trời. Thạch Hạo lấy nó từ nội khố hoàng gia và mang trên lưng.","nguon":["@c0462"]},{"id":"buc-hoa-toan-nghe-no-dua-troi-cao","name":"Bức họa Toan Nghê nô đùa trời cao","cn":"","category":"khac","categoryLabel":"Tranh truyền thừa","phamCap":"Không rõ","soHuu":[],"trangThai":"Đã bị lấy khỏi Điển miếu","blurb":"Bức họa truyền thừa ghi lại bảo thuật của Toan Nghê dị chủng và cảnh lôi điện xông phá chín tầng mây.","detail":"Bức họa từng được lưu giữ tại Điển miếu, chứa bảo thuật Toan Nghê của dị chủng. Trước khi Thạch Hạo tới nơi, nó đã bị người khác lấy đi cùng nhiều bí điển và tranh truyền thừa quý giá.","nguon":["@c0463"]},{"id":"phap-chi-vu-than","name":"Pháp chỉ Vũ Thần","cn":"","category":"phap-bao","categoryLabel":"Pháp chỉ thần linh","phamCap":"Thần linh","soHuu":["Vũ Vương"],"trangThai":"Đã bị phá hủy","blurb":"Pháp chỉ rách nát của Vũ Thần được Vũ Vương dùng máu gọi ra trên tế đàn để trấn áp Thạch Hạo.","detail":"Pháp chỉ phát sáng, dẫn theo cuồng phong và lôi điện. Thạch Hạo dùng pháp kiếm thần linh chém nó thành nhiều mảnh vụn trong trận chiến tại thần miếu Vũ Thần.","nguon":["@c0466"]},{"id":"than-kich-tran-quoc-cua-thach-toc","name":"Thần kích trấn quốc của Thạch tộc","cn":"","category":"than-khi","categoryLabel":"Thần kích","phamCap":"Trấn quốc","soHuu":["Thạch Hạo"],"trangThai":"Nguyên vẹn","blurb":"Thần kích trấn quốc chuyển từ màu đen sang màu vàng khi được rót thần lực, có sức xuyên phá pháp khí thần linh.","detail":"Thạch Hạo ném thần kích xuyên thủng tượng đá Vũ Thần rồi kéo ngược nó vào thần miếu, khiến tượng đá đâm trúng Vũ Vương. Đòn đánh làm Vũ Vương tử trận, tượng đá hóa thành bột và thần miếu sụp đổ.","nguon":["@c0466"]},{"id":"te-dan-hoang-toc-thach-quoc","name":"Tế đàn hoàng tộc Thạch Quốc","cn":"","category":"khac","categoryLabel":"Tế đàn","phamCap":"Hoàng tộc","soHuu":["Hoàng tộc Thạch Quốc"],"trangThai":"Đã kích hoạt","blurb":"Tế đàn của hoàng tộc Thạch Quốc có thể gây ảnh hưởng trên phạm vi toàn Thạch đô và phong tỏa các tế đàn truyền tống trong thành.","detail":"Tế đàn được kích hoạt trước khi Vũ tộc tìm cách đào thoát. Nó phối hợp với đại trận hộ thành, khiến tế đàn của các chư hầu không thể mở thông đạo rời khỏi Thạch đô.","nguon":["@c0466"]},{"id":"vat-chat-linh-tinh-trong-da-u-toi","name":"Vật chất linh tính trong đá u tối","cn":"","category":"nguyen-lieu","categoryLabel":"Nguyên liệu","phamCap":"Thần liệu chưa rõ phẩm cấp","soHuu":["Thạch Hạo"],"trangThai":"Đã dung hợp vào Bất Diệt Kim Thân","blurb":"Một phần vật chất cỡ móng tay ẩn trong cục đá u tối, có linh tính như mang ý thức và chủ động cộng hưởng với Bất Diệt Kim Thân.","detail":"Vật chất này giống nhựa thông, nhanh chóng hòa làm một thể với hình thái người tí hon màu đen của Bất Diệt Kim Thân. Sau khi dung hợp, chiến y xuất hiện thêm sinh cơ, gần như có chút sinh mệnh; tên gọi và lai lịch cụ thể của vật chất vẫn chưa được xác định.","nguon":["@c0467"]},{"id":"phat-tran-cua-dao-co-bo-thien-giao","name":"Phất trần của đạo cô Bổ Thiên giáo","cn":"","category":"phap-bao","categoryLabel":"Pháp khí","phamCap":"","soHuu":["Đạo cô trung niên áo trắng"],"trangThai":"Bị chém đứt","blurb":"Pháp khí có ba nghìn sợi bạc, có thể hợp lại thành dây trói để vây bắt đối thủ.","detail":"Đạo cô Bổ Thiên giáo dùng phất trần tấn công Thạch Hạo trong trận chiến tại Hoàng đô Thạch quốc. Ba nghìn sợi bạc của nó hợp thành dây trói nhưng bị kiếm khí của Thạch Hạo chém đứt.","nguon":["@c0469"]},{"id":"huyen-thuan","name":"Huyền thuẫn","cn":"","category":"phap-bao","categoryLabel":"Pháp khí phòng ngự","phamCap":"","soHuu":["Đạo cô trung niên áo trắng"],"trangThai":"Bị chém nứt","blurb":"Pháp khí phòng ngự quý giá lấy từ Bổ Thiên giáo, do một lão rùa Thần Đạo lưu lại.","detail":"Huyền thuẫn mang hình thái mai rùa màu đen và vốn được xưng là kiên cố không thể phá hủy. Khi chống đỡ pháp kiếm của Thạch Hạo, mặt thuẫn xuất hiện vết nứt rồi bị đánh bay.","nguon":["@c0469"]},{"id":"linh-tien","name":"Linh tiễn","cn":"","category":"khac","categoryLabel":"Mũi tên phù văn","phamCap":"","soHuu":["Quân phòng thủ Hoàng đô Thạch quốc"],"trangThai":"Được chuẩn bị nhưng chưa bắn","blurb":"Loại mũi tên đặc biệt dùng để đối phó đại tu sĩ, có cốt văn phát sáng trên thân.","detail":"Linh tiễn được quân phòng thủ trên tường thành Hoàng đô lắp vào cung lớn khi đối đầu sứ giả Bổ Thiên giáo. Loại tên này có thể xuyên qua thân hung thú và giết chết Vương hầu, nhưng chưa được phóng trong cuộc đối đầu.","nguon":["@c0469"]},{"id":"mai-rua-than-dao","name":"Mai rùa Thần Đạo","cn":"","category":"phap-bao","categoryLabel":"Pháp khí phòng ngự","phamCap":"Phòng ngự tuyệt phẩm","soHuu":["Đạo cô trung niên"],"trangThai":"Đã bị phá hủy","blurb":"Báu vật phòng ngự do lão rùa Thần Đạo lưu lại, từng được đạo cô trung niên dùng để chống kiếm khí của Thạch Hạo.","detail":"Mai rùa vận dụng ký hiệu để phòng ngự và cản được một phần kiếm khí màu vàng. Những vết nứt sau đó lan rộng, khiến bảo vật nổ thành hàng trăm mảnh và làm đạo cô bị thương sâu tới xương.","nguon":["@c0470"]},{"id":"chien-kiem-mau-vang","name":"Chiến kiếm màu vàng","cn":"","category":"phap-bao","categoryLabel":"Pháp khí công kích","phamCap":"Một trong hai pháp khí mạnh nhất trong bảo khố Thạch Quốc","soHuu":["Thạch Hạo"],"trangThai":"Đang được sử dụng","blurb":"Chiến kiếm sắc bén được Thạch Hạo sử dụng khi truy sát Tôn giả Bổ Thiên giáo.","detail":"Pháp khí phát ra kiếm quang màu vàng, phá hủy Mai rùa Thần Đạo và tiếp tục đánh xuyên thương đạo cô trung niên khi bà chạy khỏi Hoàng đô.","nguon":["@c0470"]},{"id":"chen-den-cua-ton-gia-tay-phuong-giao","name":"Chén đen của Tôn giả Tây Phương giáo","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Pháp khí thần linh","soHuu":["Tôn giả Tây Phương giáo cầm đầu"],"trangThai":"Đang được sử dụng","blurb":"Pháp khí cấp thần linh được dùng để trấn áp trận pháp phòng ngự của Hoàng thành Thạch Quốc.","detail":"Chiếc chén ban đầu có màu đen, tỏa ra khí lành rồi bay lên, từ từ phóng lớn và chuyển thành màu vàng. Khi ép xuống cửa thành, nó áp chế đại trận phòng ngự, khiến phù văn trên tường thành tắt hẳn và cửa thành gần như sụp đổ.","nguon":["@c0472"]},{"id":"hang-ma-xu","name":"Hàng Ma xử","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"","soHuu":["Tôn giả Tây Phương giáo cầm bình bát đen"],"trangThai":"Đã bị phá hủy","blurb":"Bảo cụ do pháp thân Kim cang diễn hóa, có thể làm chấn động pháp tắc thế gian. (+) Pháp khí cấp Thần có không gian bên trong dùng để chứa và phong kín vật phẩm. [CAN-SOAT-GOP]","detail":"Hàng Ma xử xuất hiện trong tay pháp thân Kim cang của Tôn giả Tây Phương giáo khi giao chiến với Thạch Hạo. Bảo cụ đối đầu Côn Bằng quyền nhưng bị một quyền đánh vỡ, cùng lúc pháp thân màu vàng cũng rạn nứt rồi giải thể.","nguon":["@c0474","@c0628"],"aliases":["Hàng Ma bảo xử"],"tabs":{}},{"id":"khoi-dong-thau-giam-nguyet-thien","name":"Khối đồng thau giam Nguyệt Thiền","cn":"","category":"phap-bao","categoryLabel":"Vật phẩm không gian","phamCap":"","soHuu":["Thạch Hạo"],"trangThai":"Đang được sử dụng","blurb":"Một vật phẩm không gian dùng để giam giữ Nguyệt Thiền tiên tử.","detail":"Khối đồng thau có thể phát hi quang, mở ra thông đạo màu vàng và đưa người bị giữ bên trong ra ngoài. Thạch Hạo dùng nó để thả Nguyệt Thiền tiên tử xuất hiện trước mặt Bằng Cửu và Chiến Vương.","nguon":["@c0475"]},{"id":"than-phu-pha-gioi","name":"Thần phù phá giới","cn":"","category":"phap-bao","categoryLabel":"Thần phù","phamCap":"","soHuu":["Ma nữ"],"trangThai":"Ma nữ chỉ có một tấm","blurb":"Thần phù được Ma nữ giữ làm đường lui để tránh bị giam giữ.","detail":"Có công năng phá giới, giúp người sử dụng thoát khỏi nơi giam giữ. Ma nữ từ chối đề nghị dùng ba loại thần liệu trao đổi vì nàng chỉ có một tấm và không muốn mất đi phương tiện thoát thân.","nguon":["@c0476"]},{"id":"to-te-dan-quan-sat-hoa-quoc","name":"Tổ tế đàn quan sát Hỏa quốc","cn":"","category":"khac","categoryLabel":"Tế đàn","phamCap":"Không rõ","soHuu":["Tiểu Tháp"],"trangThai":"Đã được bố trí lại sau khi mặt kính nứt vỡ","blurb":"Tổ tế đàn cho phép quan sát từ xa những biến động tại Hỏa quốc.","detail":"Sức mạnh của đại nhân vật hạ giới từng khiến mặt kính của tổ tế đàn nứt vỡ. Tiểu Tháp sau đó bố trí lại tế đàn, khôi phục khả năng truyền về hình ảnh từ Hỏa quốc ở khoảng cách cực xa.","nguon":["@c0478"]},{"id":"linh-can-de-nhat-thuong-gioi","name":"Linh căn đệ nhất của Thượng giới","cn":"","category":"nguyen-lieu","categoryLabel":"Linh căn","phamCap":"Linh căn đệ nhất của Thượng giới","soHuu":[],"trangThai":"Bị nhiều bá chủ tranh đoạt; một đóa hoa đã tách khỏi chủ thể","blurb":"Linh căn hấp thu thần tính của vùng đất cùng máu và tinh khí từ các tồn tại cấm kỵ để khôi phục thần tính.","detail":"Linh căn nằm trong sát cục ngoài Dược đô, hút thần lực và tinh khí từ khu vực rộng hàng trăm nghìn dặm. Sau khi sát trận bị phá, nó bị các bá chủ tranh đoạt và được xích thần trên đạo chung kéo về phía chủ nhân đạo chung; giữa lúc đó, một đóa hoa tách khỏi chủ thể rồi bị nữ Trùng Đồng đoạt lấy.","nguon":["@c0479"]},{"id":"dao-chung-than-bi","name":"Đạo chung thần bí","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Chí bảo","soHuu":["Chủ nhân đạo chung"],"trangThai":"Đang được dùng trong cuộc tranh đoạt linh căn","blurb":"Chuông cổ phát ra tiếng chuông mang sức mạnh thời gian, làm thời không bất ổn và công kích các bá chủ tranh linh căn.","detail":"Đạo chung có uy lực chấn động Hoang vực và phát ra sức mạnh giống như có thể đi ngược dòng sông thời gian. Trên chuông còn có xích thần dùng để khóa, kéo linh căn đệ nhất về phía chủ nhân; nó trực tiếp đối kích với khay Hỗn Độn không hoàn chỉnh trong cuộc hỗn chiến.","nguon":["@c0479"]},{"id":"khay-hon-don-khong-hoan-chinh","name":"Khay Hỗn Độn không hoàn chỉnh","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Chí bảo không hoàn chỉnh","soHuu":["Người khống chế khay Hỗn Độn không hoàn chỉnh"],"trangThai":"Không hoàn chỉnh; đang tham gia tranh đoạt linh căn","blurb":"Một chiếc khay không hoàn chỉnh phóng sương mù Hỗn Độn và cách không đối kích với đạo chung.","detail":"Khay Hỗn Độn từ trên trời lao xuống chiến trường khi các bá chủ đang tranh giành linh căn đệ nhất. Nó phóng ra sương mù Hỗn Độn, đối kích với đạo chung và khiến thiên địa chấn động.","nguon":["@c0479"]},{"id":"tan-thap-co-sinh-linh","name":"Tàn tháp có sinh linh ẩn bên trong","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Tàn khuyết","soHuu":[],"trangThai":"Đang tham gia tranh đoạt linh căn","blurb":"Một tòa tàn tháp chứa sinh linh bí ẩn lao xuống chiến trường để tranh giành linh căn đệ nhất.","detail":"Tàn tháp xuất hiện giữa cuộc hỗn chiến của các bá chủ và chí bảo. Tiểu Tháp nhận ra tòa tháp, đồng thời cảm nhận mơ hồ một sinh linh đang ẩn bên trong, nhưng quan hệ giữa hai tòa tháp chưa được xác định.","nguon":["@c0479"]},{"id":"thuyen-giay-nho-mau-den","name":"Thuyền giấy nhỏ màu đen","cn":"","category":"phap-bao","categoryLabel":"Vật phẩm","phamCap":"Chưa rõ","soHuu":["Cô gái gấp thuyền giấy"],"trangThai":"Đã xuất hiện để cản cuộc truy kích nữ Trùng Đồng","blurb":"Chiếc thuyền giấy đen vượt hư không, chặn bàn tay lớn màu tím và hóa giải các thủ đoạn truy kích nữ Trùng Đồng.","detail":"Thuyền giấy xuất hiện khi nữ Trùng Đồng mang đóa hoa phá giới rời đi. Nó chặn bàn tay màu tím đang chụp tới, đồng thời đánh tan những thần thông và chú văn vượt giới do các cường giả khác thi triển.","nguon":["@c0479"]},{"id":"sot-thuoc-cua-ba-lao","name":"Sọt thuốc của bà lão","cn":"","category":"khac","categoryLabel":"Vật phẩm","phamCap":"Chưa rõ","soHuu":["Bà lão mang sọt thuốc"],"trangThai":"Đang được dùng để thu giữ đại dược nhân gian","blurb":"Chiếc sọt được bà lão mang theo để thu giữ những sinh linh bị bà xem là đại dược nhân gian.","detail":"Bà lão không tham gia tranh đoạt vật thần thánh mà mang sọt đi săn đại dược nhân gian. Bà bắt một Tôn giả hình nhện của hồ Ma Linh và ném thẳng vào sọt trước khi rời sang những lao tù khác.","nguon":["@c0479"]},{"id":"ho-lo-lon-cua-dao-nhan","name":"Hồ lô lớn của đạo nhân","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Không nêu","soHuu":["Đạo nhân sáu tay"],"trangThai":"Đang được sử dụng","blurb":"Hồ lô phát tử quang và thụy khí, có thể thu giữ sinh linh cùng nhiều loại tài nguyên.","detail":"Đạo nhân sáu tay dùng hồ lô bắt ngân xà sắp đột phá Tôn giả và linh thú mắt xanh mắt vàng cấp Tôn giả. Tại Tây Phương giáo, pháp bảo này còn thu các đại Tôn giả, vườn thuốc và thánh vật từ một số linh sơn.","nguon":["@c0480"]},{"id":"phat-tran-cua-dao-nhan","name":"Phất trần của đạo nhân","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Không nêu","soHuu":["Đạo nhân sáu tay"],"trangThai":"Đang được sử dụng","blurb":"Phất trần có ba ngàn sợi chỉ bạc, khi thi triển hóa thành một dải ngân hà để trói bắt mục tiêu.","detail":"Đạo nhân sáu tay sử dụng phất trần tại Tây Phương giáo, khiến ba ngàn sợi chỉ bạc bay ra và hóa thành dải ngân hà, cuốn nhiều đại Tôn giả khỏi các linh sơn.","nguon":["@c0480"]},{"id":"sen-than-trong-than-tri","name":"Sen thần trong thần trì","cn":"","category":"dan-duoc","categoryLabel":"Thần dược","phamCap":"Không nêu","soHuu":["Đạo nhân sáu tay"],"trangThai":"Đã bị nhổ khỏi thần trì","blurb":"Một cây sen thần hiếm thấy sinh trưởng trong thần trì tại cung điện Tây Phương giáo.","detail":"Sen thần trôi nổi trong chất lỏng vàng óng và tỏa hào quang vô tận. Khi xâm nhập Tây Phương giáo để thanh toán nhân quả, đạo nhân sáu tay trực tiếp nhổ cây sen mang đi.","nguon":["@c0480"]},{"id":"cau-vom-mau-vang","name":"Cầu vòm màu vàng","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Không nêu","soHuu":["Trượng Lục"],"trangThai":"Đã được triệu xuất","blurb":"Chiếc cầu hình vòm màu vàng tạo thành con đường nối từ Tây Phương giáo tới vực ngoại.","detail":"Trượng Lục Kim Thân gọi ra cầu vàng để cùng đạo nhân sáu tay chuyển chiến trường tới thiên ngoại, tránh cho cuộc giao chiến của họ phá hủy tịnh thổ Tây Phương giáo phía dưới.","nguon":["@c0480"]},{"id":"phap-chi-bo-thien-giao","name":"Pháp chỉ Bổ Thiên giáo","cn":"","category":"khac","categoryLabel":"Pháp chỉ","phamCap":"Không rõ","soHuu":["Bổ Thiên giáo"],"trangThai":"Đã được Thạch Hạo tiếp nhận","blurb":"Pháp chỉ do vương hầu trung niên của Bổ Thiên giáo mang tới cho Thạch Hạo, chứa nội dung khiến hắn quyết định đến Bất Lão sơn tìm cha mẹ.","detail":"Khi được mở ra, pháp chỉ làm khí hoàng kim dâng trào, ký hiệu đại đạo hiện dày đặc và dị tượng long phượng xuất hiện. Thạch Hạo cách không lấy pháp chỉ, chặn uy thế phát ra từ thần ấn trên đó, đọc qua rồi ném sang một bên; sau đó hắn đọc kỹ lại và quyết định đích thân tới Bất Lão sơn.","nguon":["@c0481"]},{"id":"than-an-bat-lao-son-tren-phap-chi","name":"Thần ấn Bất Lão sơn trên pháp chỉ","cn":"","category":"khac","categoryLabel":"Ấn ký","phamCap":"Không rõ","soHuu":["Bất Lão sơn"],"trangThai":"Uy thế bị Thạch Hạo chặn đứng","blurb":"Đại ấn đỏ tươi do Bất Lão sơn lưu lại trên pháp chỉ, có thể phát ra thần uy xuyên qua trang giấy.","detail":"Thần ấn nằm trên pháp chỉ được đưa tới Thạch Hạo. Uy thế lớn từ đại ấn xuyên qua trang giấy phát ra ngoài nhưng bị Thạch Hạo chặn đứt.","nguon":["@c0481"]},{"id":"the-gioi-hop-quy","name":"Thế giới hộp quý","cn":"","category":"phap-bao","categoryLabel":"Không gian pháp bảo","phamCap":"Không rõ","soHuu":[],"trangThai":"Được dùng làm nơi tu dưỡng","blurb":"Một không gian pháp bảo mà Tiểu Tháp tiến vào để tu dưỡng sau đại chiến.","detail":"Sau khi trở về với bản thể bị thương và thuật lại kết quả đại kiếp, Tiểu Tháp bay vào Thế giới hộp quý để tu dưỡng trong một thời gian.","nguon":["@c0481"]},{"id":"phap-chi-cua-bat-lao-son","name":"Pháp chỉ của Bất Lão sơn","cn":"","category":"phap-bao","categoryLabel":"Pháp chỉ","phamCap":"Chưa rõ","soHuu":["Bất Lão sơn"],"trangThai":"Bị Thạch Hạo vo tròn","blurb":"Pháp chỉ do lão tổ Bất Lão sơn tự tay viết, mang bí lực và thần uy, có thể tế luyện thành pháp khí chứa khí tức thần linh.","detail":"Trên pháp chỉ có chữ vàng phát sáng và pháp tắc không tên. Tần Minh xem đây là vật quý có thể tế luyện thành pháp khí, nhưng Thạch Hạo tỏ thái độ coi nhẹ và vo tròn nó.","nguon":["@c0482"]},{"id":"thuyen-pha-khong","name":"Thuyền phá không","cn":"","category":"phap-bao","categoryLabel":"Pháp khí phi hành","phamCap":"Chưa rõ","soHuu":["Bất Lão sơn"],"trangThai":"Đã thành phế liệu","blurb":"Bảo thuyền thân xanh đen của Bất Lão sơn, dài vài trượng và dùng phù cốt nguyên thủy của phi cầm để duy trì tốc độ.","detail":"Thuyền vốn được dùng cho hành trình đường dài với tốc độ khoảng mười vạn dặm mỗi ngày. Khi Thạch Hạo dùng thần lực ép nó vượt xa giới hạn và đi mấy triệu dặm, thân tàu xuất hiện dày đặc vết nứt, phù cốt phi cầm lu mờ và toàn bộ thuyền biến thành phế liệu.","nguon":["@c0482"]},{"id":"cu-thuyen-cua-bat-lao-son-tai-huyen-vuc","name":"Cự thuyền của Bất Lão sơn tại Huyền vực","cn":"","category":"phap-bao","categoryLabel":"Pháp khí phi hành","phamCap":"Chưa rõ","soHuu":["Bất Lão sơn"],"trangThai":"Đang hoạt động","blurb":"Cự thuyền dài hàng vạn trượng, mang khí tức bất hủ và thần linh, được Bất Lão sơn điều tới đón Thạch Hạo.","detail":"Chiếc thuyền khổng lồ xuất hiện tại biên giới Huyền vực để đưa Thạch Hạo tới Bất Lão sơn. Nó có thể di chuyển khoảng một triệu dặm mỗi ngày, thích hợp cho việc vận chuyển đường dài trong Huyền vực.","nguon":["@c0482"]},{"id":"phap-thuyen-van-truong","name":"Pháp thuyền vạn trượng","cn":"","aliases":["Pháp thuyền vạn tượng"],"category":"phap-bao","categoryLabel":"Pháp thuyền","phamCap":"","soHuu":[],"trangThai":"Đang hoạt động tại Huyền vực","blurb":"Pháp thuyền chuyên chở khách qua các trọng địa của Huyền vực, mỗi ngày có thể vượt một triệu dặm.","detail":"Nhóm hậu bối thượng giới lựa chọn pháp thuyền này để du ngoạn Huyền vực và thăm các đại giáo. Thuyền có khoang khách quý ở tầng cao nhất và đạt tốc độ một triệu dặm mỗi ngày.","nguon":["@c0483"]},{"id":"tu-nguyen-thach","name":"Tụ nguyên thạch","cn":"","aliases":[],"category":"nguyen-lieu","categoryLabel":"Linh tài","phamCap":"","soHuu":[],"trangThai":"Được chế thành bàn trong khoang khách quý","blurb":"Linh tài có thể chứa linh khí thiên địa và thu hút tinh hoa từ mười phương.","detail":"Tụ nguyên thạch được dùng làm bàn trong khoang khách quý của pháp thuyền, góp phần tạo môi trường giàu nguyên khí để hỗ trợ tu hành.","nguon":["@c0483"]},{"id":"thanh-nhai-bat-lao-son","name":"Thánh nhai Bất Lão sơn","cn":"","category":"khac","categoryLabel":"Bảo cụ kiến trúc","phamCap":"","soHuu":[],"trangThai":"Đang tồn tại","blurb":"Vách đá ở khu vực ngoài Bất Lão sơn được tế luyện thành một bảo cụ kiên cố, dùng làm điểm dừng cho thuyền lớn.","detail":"Thánh nhai phủ thải quang và tiên khí, trên bề mặt có những ký hiệu như sao trời. Vách đá đã được tế luyện thành bảo cụ, tỏa bảo quang, mang đặc tính kiên cố và bất diệt.","nguon":["@c0485"]},{"id":"thuyen-lon-bat-lao-son","name":"Thuyền lớn Bất Lão sơn","cn":"","category":"khac","categoryLabel":"Phương tiện","phamCap":"","soHuu":[],"trangThai":"Đang hoạt động","blurb":"Thuyền lớn đưa đoàn Thạch Hạo vượt hơn năm triệu dặm trong năm ngày để tới khu vực ngoài Bất Lão sơn.","detail":"Sau khi đưa hành khách tới Thánh nhai Bất Lão sơn, thuyền lập tức rời đi. Trong hành trình, nó thỉnh thoảng tỏa ra khí tức thần linh.","nguon":["@c0485"]},{"id":"chien-xa-bang-dong","name":"Chiến xa bằng đồng","cn":"","category":"khac","categoryLabel":"Phương tiện","phamCap":"","soHuu":[],"trangThai":"Đang hoạt động","blurb":"Chiến xa do thụy thú kéo qua hư không, dùng để đưa khách từ thánh nhai tới sơn môn Bất Lão sơn.","detail":"Chiếc xe bằng đồng được thụy thú kéo đi giữa tiếng ầm vang, đưa Thạch Hạo từ khu vực ngoài tiến tới Bất Lão sơn thật sự.","nguon":["@c0485"]},{"id":"tu-tuyen-nhiem-khi-tuc-bao-dich-tu-phu","name":"Tử tuyền nhiễm khí tức bảo dịch Tử phủ","cn":"","category":"nguyen-lieu","categoryLabel":"Nguyên liệu","phamCap":"Linh tuyền quý hiếm","soHuu":["Bất Lão sơn"],"trangThai":"Đang được sử dụng","blurb":"Dòng linh tuyền màu tím mang hương thơm, chỉ nhiễm một tia khí tức của bảo dịch Tử phủ nhưng vẫn được xem trọng vì sản lượng rất ít.","detail":"Tử tuyền nằm gần Thần Vương điện, có lượng nước ít và được Bất Lão sơn dùng để chế thuốc cho đệ tử trẻ tuổi. Khi bị cố ý bỏ mặc, Thạch Hạo đã ngồi bên suối và dùng dòng nước quý này để ngâm chân.","nguon":["@c0486"]},{"id":"dao-lo-bat-hu","name":"Đạo lô bất hủ","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo tu luyện","phamCap":"Bất hủ","soHuu":["Bất Lão sơn"],"trangThai":"Đang dùng làm nơi tu luyện","blurb":"Đạo lô đặt tại vùng Bất lão, nơi cha mẹ Thạch Hạo được bố trí tu luyện trong môi trường có pháp tắc đầy đủ và đại đạo thiên địa bao phủ.","detail":"Đạo lô bất hủ giúp nâng cao đáng kể hiệu quả tu hành. Nó nằm trong khu vực hạn chế của Bất Lão sơn, nơi thông thường chỉ những lão tổ cấp Thần linh mới có tư cách tiến vào.","nguon":["@c0486"]},{"id":"chien-y-bat-diet-mau-den","name":"Chiến y bất diệt màu đen","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Báu vật Thái cổ không trọn vẹn","soHuu":["Thạch Hạo"],"trangThai":"Không trọn vẹn, có thể sửa chữa","blurb":"Một người tí hon màu đen có thể hóa thành chiến y bất diệt và dung hợp với Thạch Hạo.","detail":"Chiến y có nguồn gốc từ thời Thái cổ. Khi dung hợp với Thạch Hạo, nó giúp người mặc thể hiện chiến lực cấp Tôn giả và áp đảo Tần Pháp ngay trong lần tiếp xúc đầu tiên; tuy không trọn vẹn, vật này vẫn có khả năng được sửa chữa.","nguon":["@c0487"]},{"id":"chien-y-than-linh-mau-bac","name":"Chiến y Thần linh màu bạc","cn":"","category":"phap-bao","categoryLabel":"Chiến y","phamCap":"Thần linh","soHuu":["Tần Hạo"],"trangThai":"Đang được sử dụng","blurb":"Chiến y màu bạc lưu chuyển sức mạnh Thần linh mênh mông, khiến Tần Hạo vượt khỏi vẻ phàm tục.","detail":"Tần Hạo mặc chiến y này khi xuất hiện trước Thạch Hạo. Sức mạnh Thần linh lưu chuyển trên chiến y cho thấy phẩm chất bất phàm và mang lại uy thế mạnh mẽ cho người mặc.","nguon":["@c0488"]},{"id":"chien-mau-mau-bac","name":"Chiến mâu màu bạc","cn":"","category":"phap-bao","categoryLabel":"Chiến mâu","phamCap":"","soHuu":["Tần Hạo"],"trangThai":"Đang được sử dụng","blurb":"Chiến mâu màu bạc được Tần Hạo dùng để khóa vào sau ót Thạch Hạo khi ngăn cản việc giết Tần Pháp.","detail":"Tần Hạo cầm chiến mâu nhắm vào sau ót Thạch Hạo từ phía sau, sau đó thu binh khí lại khi lên tiếng yêu cầu tha mạng cho Tần Pháp.","nguon":["@c0488"]},{"id":"ngu-hanh-son","name":"Ngũ Hành sơn","cn":"","category":"than-khi","categoryLabel":"Chí bảo dạng núi","phamCap":"Có khả năng là chí bảo đáng sợ","soHuu":[],"trangThai":"Đang trấn tại Bất Lão sơn","blurb":"Pháp khí bảo vệ địa bàn Bất Lão Sơn, đồng thời phối hợp với Bất Lão Thiên Tôn trấn áp sinh linh bất diệt. (+) Năm ngọn núi tại Bất Lão sơn có dấu hiệu dẫn động và áp chế thần kích trấn quốc của Thạch tộc. [CAN-SOAT-GOP]","detail":"Khi đại trận Bất Lão sơn được kích hoạt, thần kích trấn quốc rung chuyển dữ dội và muốn bay về phía năm ngọn núi. Từ hiện tượng này, Thạch Hạo nhận định Ngũ Hành sơn ít nhất có khả năng là một chí bảo đáng sợ.","nguon":["@c0489","@c0501"]},{"id":"huyet-thanh-than-thanh-nam-mau","name":"Huyết thanh thần thánh năm màu","cn":"","category":"khac","categoryLabel":"Bảo dịch niết bàn","phamCap":"","soHuu":["Tần Trạm"],"trangThai":"Bị phá tan","blurb":"Bảo dịch năm màu hình thành từ thần năng và pháp lực chảy ra khỏi cốt tủy Tần Trạm, bao bọc lão như một chiếc kén trong quá trình niết bàn.","detail":"Huyết thanh lưu giữ phù văn và áo nghĩa bất diệt, đồng thời có thể ghi nhận pháp đạo từ ngoại giới. Tần Trạm định lợi dụng nó để niết bàn và sao chép bảo thuật của Thạch Hạo, nhưng lớp bảo dịch bị Côn Bằng nhỏ xuyên thủng; sau đó Thạch Hạo thăm dò phần huyết thanh chảy ra và thu gom các ký hiệu của Ngũ hành niết bàn.","nguon":["@c0490"]},{"id":"phap-kiem-than-linh-mau-vang","name":"Pháp kiếm thần linh màu vàng","cn":"","aliases":["Pháp kiếm vàng"],"category":"than-khi","categoryLabel":"Thần khí","phamCap":"Thần khí trấn quốc","soHuu":["Thạch Hạo"],"trangThai":"Đang được sử dụng","blurb":"Thần khí trấn quốc của Thạch tộc, được Thạch Hạo dùng khi giao chiến tại Cốc thần.","detail":"Pháp kiếm phát ra thần mang và thần uy mạnh mẽ, chém vào ngân mâu rồi đẩy lui Tần Hạo cùng hai ông lão Bất Lão sơn đang liên thủ.","nguon":["@c0491"]},{"id":"sach-quy-co-phap-niet-ban","name":"Sách quý cổ pháp niết bàn","cn":"","aliases":[],"category":"khac","categoryLabel":"Pháp quyết hữu hình","phamCap":"Cổ pháp hoàn thiện","soHuu":["Thạch Hạo"],"trangThai":"Đã nhập vào cơ thể Thạch Hạo","blurb":"Hình thái hữu hình của thiên cổ pháp niết bàn hoàn chỉnh mà Thạch Hạo tinh luyện từ Tần Trạm.","detail":"Các đạo phù kết thành những trang sách vàng óng trong hư không. Sau khi hình thành, sách quý biến thành một dải sáng như ngân hà, nhập vào cơ thể và khắc rõ toàn bộ pháp quyết trong đầu Thạch Hạo.","nguon":["@c0491"]},{"id":"buc-tranh-hoang-kim","name":"Bức tranh hoàng kim","cn":"","category":"phap-bao","categoryLabel":"Pháp bảo","phamCap":"Chưa rõ","soHuu":["Tần Nhất Phàm"],"trangThai":"Đã thu hồi","blurb":"Pháp bảo do hình chiếu của Tần Nhất Phàm điều khiển, có thể cuốn người đi và bảo vệ chủ nhân.","detail":"Bức tranh tựa như một thế giới hư vô, khiến pháp kiếm trấn quốc dù có thể chém hư không vẫn không chạm được vào nó. Tần Nhất Phàm dùng vật này định cuốn Thạch Hạo rời khỏi Bất Lão sơn, sau đó thu lại để quấn quanh và hộ thân khi tiến vào hư không.","nguon":["@c0492"]},{"id":"te-dan-dong","name":"Tế đàn đồng","cn":"","category":"khac","categoryLabel":"Vật phẩm trận pháp","phamCap":"Chưa rõ","soHuu":["Tần Vũ"],"trangThai":"Đang được sử dụng tại Bất Lão sơn","blurb":"Tế đàn đặt trước đại điện đồng, được Tần Vũ dùng làm điểm vận chuyển trận pháp liên hệ với thượng giới.","detail":"Tế đàn được đúc bằng đồng, bên trên còn có những vết máu hiến tế phát sáng. Khi Tần Vũ đóng trận pháp tại đây, Bất Lão sơn bị ngăn cách với thượng giới, khiến hình chiếu và bức tranh hoàng kim của Tần Nhất Phàm nhanh chóng suy yếu.","nguon":["@c0492"]},{"id":"nam-ho-niet-ban","name":"Năm hồ niết bàn","cn":"","category":"khac","categoryLabel":"Vật phẩm niết bàn","phamCap":"Không rõ","soHuu":["Bất Lão sơn"],"trangThai":"Đang vận hành trong chiến trường anh linh","blurb":"Năm hồ tương ứng với năm cảnh giới Thạch Hạo từng tu luyện, có khả năng khắc lại bí mật và pháp môn khi thần hồn mục tiêu rời thể xác.","detail":"Đây là khu vực duy nhất cuồn cuộn dương khí và sóng nhiệt giữa chiến trường anh linh. Khi thần hồn Thạch Hạo bị linh vực màu bạc kéo khỏi thân thể, cả năm hồ đồng loạt sôi trào, hiện lên đạo vận như muốn khắc lại toàn bộ bí mật và pháp môn của hắn.","nguon":["@c0493"]},{"id":"chien-mau-than-linh-cua-tan-hao","name":"Chiến mâu thần linh của Tần Hạo","cn":"","category":"than-khi","categoryLabel":"Thần khí","phamCap":"Không rõ","soHuu":["Tần Hạo"],"trangThai":"Đang được sử dụng","blurb":"Chiến mâu do Tần Hạo cầm khi tiến vào trận, dùng để tấn công thực thể hình thành từ chiến ý và pháp lực của Thạch Hạo.","detail":"Tần Hạo mặc chiến y màu bạc, cầm chiến mâu thần linh chỉ về phía mi tâm đối thủ rồi tung ra một đòn bén nhọn trong cuộc giao chiến do Hóa ma trận tạo nên.","nguon":["@c0493"]},{"id":"phap-truong-vang-ong-cua-anh-linh","name":"Pháp trượng vàng óng của anh linh","cn":"","category":"than-khi","categoryLabel":"Thần khí","phamCap":"Không rõ","soHuu":["Anh linh màu vàng nhạt"],"trangThai":"Xuất hiện trong chiến trường anh linh","blurb":"Thần khí của một hồn thể màu vàng nhạt, có thể phóng ra lửa linh hồn cùng các ký hiệu để uy hiếp Thạch Hạo.","detail":"Pháp trượng vàng óng được anh linh sử dụng giữa cuộc vây giết trong chiến trường thượng cổ. Công kích phát ra từ pháp trượng mang theo lửa linh hồn và ký hiệu, đủ sức tạo thành uy hiếp đối với Thạch Hạo.","nguon":["@c0493"]},{"id":"dao-gam-lo-mo","name":"Dao găm lờ mờ","cn":"","category":"phap-bao","categoryLabel":"Pháp khí","phamCap":"Không rõ","soHuu":["Thạch Tử Lăng"],"trangThai":"Được dùng để phá trận","blurb":"Pháp khí do vợ Thạch Tử Lăng trao cho chồng, có khả năng cắt đứt không gian trận pháp.","detail":"Sau khi cảm ứng được phương vị của hai con, Thạch Tử Lăng nhận dao găm từ thê tử và kích phát nó. Trên pháp khí hiện ra ký hiệu dày đặc, sức cắt mạnh đến mức xé mở không gian đang giam giữ họ.","nguon":["@c0493"]},{"id":"than-kich-tran-quoc","name":"Thần kích trấn quốc","cn":"","category":"than-khi","categoryLabel":"Thần khí","phamCap":"Thần khí trấn quốc","soHuu":["Thạch Hạo"],"trangThai":"Đang được sử dụng","blurb":"Thần kích được Thạch Hạo cầm khi chiến ý bùng nổ trong trận chiến tại Bất Lão sơn.","detail":"Thần kích cùng pháp kiếm gia trì uy thế khi Chí Tôn cốt của Thạch Hạo thức tỉnh để luyện hóa thần huyết của Tần Vũ.","nguon":["@c0494"]},{"id":"than-huyet-cua-tan-vu","name":"Thần huyết của Tần Vũ","cn":"","category":"nguyen-lieu","categoryLabel":"Nguyên liệu","phamCap":"Thần huyết","soHuu":["Tần Vũ"],"trangThai":"Đã bị luyện hóa","blurb":"Một giọt thần huyết được Tần Vũ dùng để áp chế và luyện hóa đạo hạnh của Thạch Hạo.","detail":"Giọt máu mang thần năng được tuyên bố có thể hòa tan đạo hạnh và thần thông, nhưng cuối cùng bị Chí Tôn cốt của Thạch Hạo hấp thu hoàn toàn làm chất dinh dưỡng.","nguon":["@c0494"]},{"id":"chi-ton-cot-cua-thach-hao","name":"Chí tôn cốt của Thạch Hạo","cn":"","category":"khac","categoryLabel":"Bảo cốt","phamCap":"","soHuu":["Thạch Hạo"],"trangThai":"Đang thức động","blurb":"Bảo cốt trong cơ thể Thạch Hạo có thể chủ động luyện hóa tinh hoa bản nguyên từ thân thể thần linh thành sức mạnh thần tính.","detail":"Khi cánh tay của Tần Vũ nổ tung thành tinh hoa bản nguyên, Chí tôn cốt tự phát sáng và hiện ra một người tí hon cao bằng nắm đấm ngồi xếp bằng trên cốt. Tiếng tụng kinh vang lên trong lúc nó hấp thu tinh hoa thần tính màu bạc từ cả hai cánh tay bị phá hủy, qua đó bổ sung sức sống và sức mạnh thần tính cho bản thân.","nguon":["@c0495"]},{"id":"ngu-hanh-son-phap-bao","name":"Ngũ hành sơn","cn":"","category":"than-khi","categoryLabel":"Tiên thiên thần sơn","phamCap":"Sinh ra trong hỗn độn trước khai thiên","soHuu":["Bất Lão sơn"],"trangThai":"Đã thức tỉnh, bị Tiểu Tháp đánh lệch khỏi vị trí trấn áp","blurb":"Tiên thiên thần sơn có ý chí, tồn tại từ trước khai thiên và là lực lượng trấn thủ của Bất Lão sơn.","detail":"Ngũ hành sơn có thể phát ra thần năng đối kháng Tiểu Tháp và trấn áp một sinh linh bằng xích thần ngũ hành. Sau cuộc va chạm với Tiểu Tháp, ngọn núi bị đẩy khỏi vị trí, khiến sinh linh bị phong ấn bên dưới lộ diện.","nguon":["@c0496"]},{"id":"phap-kiem-cua-thach-hao","name":"Pháp kiếm của Thạch Hạo","cn":"","category":"phap-bao","categoryLabel":"Chiến kiếm","phamCap":"Có thể sát thương Thần linh","soHuu":["Thạch Hạo"],"trangThai":"Đang được sử dụng","blurb":"Chiến kiếm được Thạch Hạo dùng khi truy hỏi người của Bất Lão sơn và giao chiến với Tần Vũ.","detail":"Pháp kiếm có thể hóa thành Toan Nghê màu vàng mang theo sấm chớp, đánh Tần Pháp thành tro. Kiếm còn bùng phát kiếm khí hỗn độn, đánh nát Thần linh Tần Vũ thành sương máu.","nguon":["@c0496"]},{"id":"xich-than-ngu-hanh","name":"Xích thần ngũ hành","cn":"","category":"phap-bao","categoryLabel":"Vật phong ấn","phamCap":"","soHuu":["Bất Lão sơn"],"trangThai":"Đang trói buộc sinh linh bị trấn áp","blurb":"Xích thần mang lực lượng ngũ hành, được dùng để trói buộc sinh linh nằm dưới Ngũ hành sơn.","detail":"Khi Ngũ hành sơn bị Tiểu Tháp đánh rời khỏi vị trí, xích thần ngũ hành cùng sinh linh gầy gò bị trói bên dưới đã lộ ra trước người Tần tộc.","nguon":["@c0496"]},{"id":"vong-than-ngu-hanh","name":"Vòng thần Ngũ hành","cn":"","category":"phap-bao","categoryLabel":"Pháp khí","phamCap":"Một trong các pháp khí mạnh nhất thời thượng cổ","soHuu":["Bất Lão sơn"],"trangThai":"Đang tồn tại","blurb":"Pháp khí nổi danh của Bất Lão sơn, được cổ nhân mô phỏng từ đạo văn và dấu vết đại đạo của Ngũ Hành sơn.","detail":"Vòng thần Ngũ hành từng uy chấn tám vực và được đánh giá rất cao trong hàng ngũ binh khí thời thượng cổ. Tuy nhiên, pháp khí này chỉ là sản phẩm mô phỏng Ngũ Hành sơn, không thể sánh với nguyên thể sinh ra trong hỗn độn.","nguon":["@c0497"]},{"id":"te-dan-mau-do-sam","name":"Tế đàn màu đỏ sậm","cn":"","category":"khac","categoryLabel":"Vật phẩm phong ấn","phamCap":"Chưa rõ","soHuu":[],"trangThai":"Bị sinh linh bất diệt oanh kích","blurb":"Tế đàn nằm dưới mặt đất, kết nối với xích thần Ngũ hành và giữ vai trò đầu mối trong hệ thống trấn phong.","detail":"Tế đàn màu đỏ sậm hiện ra bên dưới điểm neo của xích thần Ngũ hành, trên bề mặt phủ vô số ký hiệu. Sinh linh bất diệt liên tục kéo xích và oanh kích tế đàn nhằm phá hủy hệ thống phong ấn.","nguon":["@c0498"]},{"id":"dao-gam-xuong-hu-khong-thu","name":"Dao găm xương Hư Không Thú","cn":"","category":"phap-bao","categoryLabel":"Vũ khí","phamCap":"Không rõ","soHuu":["Thạch Tử Lăng","Tần Di Ninh"],"trangThai":"Đang được sử dụng","blurb":"Dao găm được tế luyện từ xương Hư Không Thú, có khả năng chém vào hư không.","detail":"Thạch Tử Lăng và Tần Di Ninh liên tục dùng dao găm này chém vào hư không nhằm tìm đường rời khỏi sơn cốc bị trận pháp phong tỏa, nhưng vẫn chưa thể thoát ra.","nguon":["@c0499"]}]};